#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct ShareModelCooldownKey {
    share_id: String,
    runtime_fingerprint: String,
    model: String,
}

#[derive(Debug, Clone, Copy)]
