#[derive(Debug, Clone)]
struct DeviceFlowPrincipalBinding {
    principal_id: String,
    expires_at_ms: i64,
}

#[derive(Debug, Default)]
struct DeviceFlowPrincipalStore {
    bindings: BTreeMap<(String, String), DeviceFlowPrincipalBinding>,
}

impl DeviceFlowPrincipalStore {
    fn insert(
        &mut self,
        provider_type: ProviderType,
        device_code: String,
        principal_id: String,
        expires_at_ms: i64,
        now_ms: i64,
    ) {
        self.cleanup(now_ms);
        self.bindings.insert(
            (provider_type.as_str().to_string(), device_code),
            DeviceFlowPrincipalBinding {
                principal_id,
                expires_at_ms,
            },
        );
    }

    fn is_owned_by(
        &mut self,
        provider_type: ProviderType,
        device_code: &str,
        principal_id: &str,
        now_ms: i64,
    ) -> bool {
        self.cleanup(now_ms);
        self.bindings
            .get(&(provider_type.as_str().to_string(), device_code.to_string()))
            .is_some_and(|binding| binding.principal_id == principal_id)
    }

    fn remove_for_principal(
        &mut self,
        provider_type: ProviderType,
        device_code: &str,
        principal_id: &str,
        now_ms: i64,
    ) -> bool {
        self.cleanup(now_ms);
        let key = (provider_type.as_str().to_string(), device_code.to_string());
        if self
            .bindings
            .get(&key)
            .is_none_or(|binding| binding.principal_id != principal_id)
        {
            return false;
        }
        self.bindings.remove(&key).is_some()
    }

    fn remove_all_for_principal(
        &mut self,
        provider_type: ProviderType,
        principal_id: &str,
        now_ms: i64,
    ) -> Vec<String> {
        self.cleanup(now_ms);
        let provider_type = provider_type.as_str();
        let device_codes = self
            .bindings
            .iter()
            .filter(|((binding_provider_type, _), binding)| {
                binding_provider_type.as_str() == provider_type
                    && binding.principal_id == principal_id
            })
            .map(|((_, device_code), _)| device_code.clone())
            .collect::<Vec<_>>();
        for device_code in &device_codes {
            self.bindings
                .remove(&(provider_type.to_string(), device_code.clone()));
        }
        device_codes
    }

    fn cleanup(&mut self, now_ms: i64) {
        self.bindings
            .retain(|_, binding| binding.expires_at_ms > now_ms);
    }
}

