    pub async fn read_router_log_tail(
        &self,
        requested_lines: usize,
    ) -> Result<LogTailResponse, LogTailAccessError> {
        let store = self.ui_settings.read().await;
        let config = ui_settings::parse_log_config(&ui_settings::log_config_for_frontend(&store));
        drop(store);
        if !config.enabled
            || !config.collection_enabled
            || !config.level.eq_ignore_ascii_case("info")
        {
            return Err(LogTailAccessError::Disabled);
        }
        Ok(self
            .log_capture
            .read_current_process_tail(requested_lines.clamp(1, 100)))
    }

    pub(crate) async fn store_image_capability(
        &self,
        data: bytes::Bytes,
        mime_type: String,
    ) -> anyhow::Result<crate::image_store::ImageCapabilityHandle> {
        let store = Arc::clone(&self.image_capabilities);
        tokio::task::spawn_blocking(move || store.insert(data, mime_type))
            .await
            .context("join image capability insert task")?
    }

    pub(crate) async fn image_capability(
        &self,
        token: String,
    ) -> anyhow::Result<Option<crate::image_store::ImageCapability>> {
        let store = Arc::clone(&self.image_capabilities);
        tokio::task::spawn_blocking(move || store.get(&token))
            .await
            .context("join image capability read task")?
    }

    pub async fn read_admin_log_tail(
        &self,
        requested_lines: Option<usize>,
    ) -> Result<LogTailResponse, LogTailAccessError> {
        let store = self.ui_settings.read().await;
        let config = ui_settings::parse_log_config(&ui_settings::log_config_for_frontend(&store));
        let api_config = ui_settings::parse_api_management_config(
            &ui_settings::api_management_config_for_frontend(&store),
        );
        drop(store);
        if !config.enabled || !api_config.log_enabled {
            return Err(LogTailAccessError::Disabled);
        }
        let lines = crate::logging::clamp_tail_lines(requested_lines, api_config.log_tail_lines);
        Ok(self.log_capture.read_tail(&config, &self.config_dir, lines))
    }

    pub async fn replace_config(&self, mut config: ServerConfig) -> anyhow::Result<()> {
        let _commit = self.config_persistence.gate.lock().await;
        let current = self.config.read().await.clone();
        preserve_router_identity_from_stale_snapshot(&current, &mut config);
        preserve_setup_completion_from_stale_snapshot(&current, &mut config);
        preserve_client_tunnel_claim_from_stale_snapshot(&current, &mut config);
        preserve_client_subdomain_adoption_from_stale_snapshot(&current, &mut config);
        config.provider_runtime_defaults = current.provider_runtime_defaults.clone();
        let http_client = build_http_client()?;
        persist_state_snapshot(&self.config_dir, config.clone()).await?;
        *self.http_client.write().await = http_client;
        *self.config.write().await = config;
        self.config_persistence.mark_published();
        Ok(())
    }

    async fn mutate_config_immediate<R>(
        &self,
        mutate: impl FnOnce(&mut ServerConfig) -> anyhow::Result<R>,
    ) -> anyhow::Result<R> {
        let _commit = self.config_persistence.gate.lock().await;
        let mut candidate = self.config.read().await.clone();
        let result = mutate(&mut candidate)?;
        #[cfg(test)]
        self.config_persistence.apply_test_persist_delay().await;
        persist_state_snapshot(&self.config_dir, candidate.clone()).await?;
        *self.config.write().await = candidate;
        self.config_persistence.mark_published();
        Ok(result)
    }

    pub async fn set_upgrade_policy(
        &self,
        policy: crate::domain::settings::config::UpgradePolicyConfig,
    ) -> anyhow::Result<()> {
        self.mutate_config_immediate(|config| {
            config.upgrade_policy = policy;
            Ok(())
        })
        .await
    }

    pub async fn set_provider_runtime_defaults(
        self: &Arc<Self>,
        defaults: ProviderRuntimeDefaults,
    ) -> anyhow::Result<()> {
        defaults.validate()?;
        let _references = self.reference_mutations.lock().await;
        let _provider_commit = self.provider_commits.lock().await;
        let provider_keys = {
            let _config_commit = self.config_persistence.gate.lock().await;
            let mut candidate_config = self.config.read().await.clone();
            candidate_config.provider_runtime_defaults = defaults.clone();
            let mut candidate_providers = self.providers.read().await.clone();
            let accounts = self.accounts.read().await.clone();
            candidate_providers.set_runtime_defaults(defaults);
            candidate_providers
                .rebuild_runtime_index(&accounts)
                .context("compile Provider runtime index for Server defaults")?;
            let provider_keys = candidate_providers
                .providers
                .iter()
                .map(|provider| (provider.app, provider.provider.id.clone()))
                .collect::<BTreeSet<_>>();

            persist_state_snapshot(&self.config_dir, candidate_config.clone()).await?;
            *self.config.write().await = candidate_config;
            *self.providers.write().await = candidate_providers;
            self.config_persistence.mark_published();
            provider_keys
        };

        let providers = self.providers.read().await.clone();
        let accounts = self.accounts.read().await.clone();
        let usage = self.usage.read().await.clone();
        let refreshed_share_ids = self
            .mutate_shares_immediate(|shares| {
                shares.reconcile_runtime_snapshots_for_providers(
                    &provider_keys,
                    &providers,
                    Some(&accounts),
                    &usage,
                )
            })
            .await?;
        let share_ids = {
            let shares = self.shares.read().await;
            provider_keys
                .iter()
                .flat_map(|(app, provider_id)| shares.share_ids_for_provider(*app, provider_id))
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>()
        };
        if !refreshed_share_ids.is_empty() {
            self.emit_event(
                ServerEvent::new("share.changed", "share")
                    .message("provider_runtime_defaults_updated"),
            );
        }
        let router_registered = self
            .config_snapshot()
            .await
            .has_registered_router_identity();
        let force_router_sync = !refreshed_share_ids.is_empty();
        drop(_provider_commit);
        drop(_references);
        if router_registered && !share_ids.is_empty() {
            let state = self.clone();
            tokio::spawn(async move {
                if let Err(error) =
                    sync_shares_to_router_with_policy(&state, &share_ids, force_router_sync).await
                {
                    tracing::warn!(
                        share_count = share_ids.len(),
                        %error,
                        "Provider runtime defaults Share projection sync remains pending"
                    );
                }
            });
        }
        Ok(())
    }

    pub async fn config_snapshot(&self) -> ServerConfig {
        self.config.read().await.clone()
    }

    pub(crate) async fn prepare_client_subdomain_adoption(
        &self,
        takeover_id: &str,
        from_subdomain: &str,
        to_subdomain: &str,
        activate_at_ms: i64,
    ) -> anyhow::Result<ClientSubdomainAdoption> {
        let takeover_id = takeover_id.trim();
        if takeover_id.is_empty() || takeover_id.len() > 128 {
            anyhow::bail!("takeoverId must be a non-empty identifier of at most 128 bytes");
        }
        let from_subdomain = ClientSubdomain::parse(from_subdomain)?.to_string();
        let to_subdomain = ClientSubdomain::parse(to_subdomain)?.to_string();
        if from_subdomain == to_subdomain {
            anyhow::bail!("source and destination Client subdomains must differ");
        }
        let now = now_ms_i64();

        let _workspace_transaction = self.codex_workspace_rebind_transactions.lock().await;
        self.recover_pending_codex_workspace_rebind_transaction(
            "Client subdomain adoption prepare",
        )?;
        self.mutate_config_immediate(|config| {
        if let Some(existing) = config.client.subdomain_adoption.as_ref() {
            if existing.takeover_id == takeover_id {
                if existing.from_subdomain != from_subdomain
                    || existing.to_subdomain != to_subdomain
                {
                    anyhow::bail!("takeoverId is already bound to a different adoption");
                }
                return Ok(existing.clone());
            }
            if existing.status == ClientSubdomainAdoptionStatus::Prepared {
                anyhow::bail!("another Client subdomain adoption is already prepared");
            }
        }
        if activate_at_ms > now.saturating_add(CLIENT_SUBDOMAIN_ADOPTION_MAX_FUTURE_MS) {
            anyhow::bail!("activateAtMs is outside the allowed activation window");
        }
        let configured_subdomain = config
            .client
            .tunnel_subdomain
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| anyhow::anyhow!("client tunnel subdomain is not configured"))?;
        if configured_subdomain != from_subdomain {
            anyhow::bail!(
                "client subdomain changed before adoption prepare: expected {from_subdomain}, found {configured_subdomain}"
            );
        }

        let adoption = ClientSubdomainAdoption {
            takeover_id: takeover_id.to_string(),
            from_subdomain,
            to_subdomain,
            status: ClientSubdomainAdoptionStatus::Prepared,
            activate_at_ms,
            prepared_at_ms: now,
            committed_at_ms: None,
        };
        config.client.subdomain_adoption = Some(adoption.clone());
        Ok(adoption)
        })
        .await
    }

    pub(crate) async fn commit_client_subdomain_adoption(
        &self,
        takeover_id: &str,
    ) -> anyhow::Result<(ClientSubdomainAdoption, bool)> {
        // Keep the persistent-store lock order aligned with backup restore/reload:
        // workspace transaction -> config -> Shares. The previous config -> workspace
        // order could deadlock against a concurrent persistent-store reload.
        let _workspace_transaction = self.codex_workspace_rebind_transactions.lock().await;
        self.recover_pending_codex_workspace_rebind_transaction("Client subdomain adoption")?;
        let _config_commit = self.config_persistence.gate.lock().await;
        let _shares_commit = self.shares_persistence.gate.lock().await;
        let current = self.config.read().await.clone();
        let adoption = current
            .client
            .subdomain_adoption
            .as_ref()
            .filter(|adoption| adoption.takeover_id == takeover_id.trim())
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("prepared Client subdomain adoption was not found"))?;
        if adoption.status == ClientSubdomainAdoptionStatus::Committed {
            return Ok((adoption, false));
        }
        if current.client.tunnel_subdomain.as_deref() != Some(adoption.from_subdomain.as_str()) {
            anyhow::bail!("client subdomain changed after adoption prepare");
        }

        let from_client = ClientSubdomain::parse(&adoption.from_subdomain)?;
        let to_client = ClientSubdomain::parse(&adoption.to_subdomain)?;
        let mut candidate_shares = self.shares.read().await.clone();
        let rebased_shares =
            candidate_shares.rebase_full_tunnel_subdomains(&from_client, &to_client);
        persist_state_snapshot(&self.config_dir, candidate_shares.clone()).await?;

        let mut committed = adoption;
        committed.status = ClientSubdomainAdoptionStatus::Committed;
        committed.committed_at_ms = Some(now_ms_i64());
        let mut next = current;
        next.client.tunnel_subdomain = Some(committed.to_subdomain.clone());
        next.client.tunnel_status = Some("claimed_remote".to_string());
        next.client.claim_pending = None;
        next.client.subdomain_adoption = Some(committed.clone());
        persist_state_snapshot(&self.config_dir, next.clone()).await?;
        *self.shares.write().await = candidate_shares;
        *self.config.write().await = next;
        self.shares_persistence.mark_published();
        self.config_persistence.mark_published();
        if rebased_shares > 0 {
            tracing::info!(
                takeover_id = %committed.takeover_id,
                rebased_shares,
                "rebased persisted Share subdomains for Client adoption"
            );
        }
        Ok((committed, true))
    }

    pub(crate) async fn abort_client_subdomain_adoption(
        &self,
        takeover_id: &str,
    ) -> anyhow::Result<bool> {
        let _workspace_transaction = self.codex_workspace_rebind_transactions.lock().await;
        self.recover_pending_codex_workspace_rebind_transaction("Client subdomain adoption abort")?;
        self.mutate_config_immediate(|config| {
            let Some(adoption) = config.client.subdomain_adoption.as_ref() else {
                return Ok(false);
            };
            if adoption.takeover_id != takeover_id.trim() {
                anyhow::bail!("prepared Client subdomain adoption was not found");
            }
            if adoption.status == ClientSubdomainAdoptionStatus::Committed {
                anyhow::bail!("committed Client subdomain adoption cannot be aborted");
            }
            config.client.subdomain_adoption = None;
            Ok(true)
        })
        .await
    }

    pub(crate) async fn lock_client_tunnel_claim(&self) -> tokio::sync::MutexGuard<'_, ()> {
        self.client_tunnel_claim.lock().await
    }

    pub(crate) async fn begin_client_tunnel_claim(
        &self,
        intent: &ClientTunnelClaimIntent,
    ) -> anyhow::Result<ServerConfig> {
        self.mutate_config_immediate(|config| {
            if !intent.matches_config(config) {
                anyhow::bail!("client tunnel claim configuration changed before intent commit");
            }
            config.client.claim_pending = Some(intent.clone());
            config.client.tunnel_status = Some("claim_pending".to_string());
            config.router.last_register_error = None;
            Ok(config.clone())
        })
        .await
    }

    pub(crate) async fn commit_client_tunnel_claim_success(
        &self,
        intent: &ClientTunnelClaimIntent,
    ) -> anyhow::Result<ServerConfig> {
        self.mutate_config_immediate(|config| {
            ensure_current_client_tunnel_claim(config, intent)?;
            config.client.claim_pending = None;
            config.client.tunnel_status = Some("claimed_remote".to_string());
            config.router.last_register_error = None;
            #[cfg(test)]
            if self
                .client_tunnel_claim_commit_failures
                .fetch_update(
                    std::sync::atomic::Ordering::AcqRel,
                    std::sync::atomic::Ordering::Acquire,
                    |remaining| remaining.checked_sub(1),
                )
                .is_ok()
            {
                anyhow::bail!("injected client tunnel claim commit failure");
            }
            Ok(config.clone())
        })
        .await
    }

    pub(crate) async fn commit_client_tunnel_claim_failure(
        &self,
        intent: &ClientTunnelClaimIntent,
        conflict: bool,
        message: String,
    ) -> anyhow::Result<ServerConfig> {
        self.mutate_config_immediate(|config| {
            ensure_current_client_tunnel_claim(config, intent)?;
            config.client.claim_pending = None;
            config.client.tunnel_status = Some(if conflict {
                "claim_conflict".to_string()
            } else {
                "claim_failed".to_string()
            });
            config.router.last_register_error = Some(message);
            Ok(config.clone())
        })
        .await
    }

    pub(crate) async fn retain_client_tunnel_claim_pending(
        &self,
        intent: &ClientTunnelClaimIntent,
        message: String,
    ) -> anyhow::Result<ServerConfig> {
        self.mutate_config_immediate(|config| {
            ensure_current_client_tunnel_claim(config, intent)?;
            config.client.tunnel_status = Some("claim_pending".to_string());
            config.router.last_register_error = Some(message);
            Ok(config.clone())
        })
        .await
    }

    pub(crate) async fn mark_client_tunnel_claim_skipped(&self) -> anyhow::Result<ServerConfig> {
        let _claim = self.client_tunnel_claim.lock().await;
        self.mutate_config_immediate(|config| {
            if config.client.claim_pending.is_none()
                && matches!(
                    config.client.tunnel_status.as_deref(),
                    Some("claimed_remote" | "connected" | "active" | "running")
                )
            {
                return Ok(config.clone());
            }
            config.client.tunnel_status = Some("claim_skipped".to_string());
            Ok(config.clone())
        })
        .await
    }

    pub(crate) async fn commit_client_tunnel_lease(
        &self,
        intent: &ClientTunnelClaimIntent,
        ssh_host: String,
    ) -> anyhow::Result<ServerConfig> {
        self.mutate_config_immediate(|config| {
            if !intent.matches_config(config) {
                anyhow::bail!("client tunnel configuration changed before lease commit");
            }
            config.client.tunnel_status = Some("connected".to_string());
            config.router.ssh_host = Some(ssh_host);
            Ok(config.clone())
        })
        .await
    }

    pub(crate) async fn record_client_tunnel_heartbeat(
        &self,
        heartbeat_ms: u128,
    ) -> anyhow::Result<ServerConfig> {
        self.mutate_config_immediate(|config| {
            config.client.last_heartbeat_ms = Some(heartbeat_ms);
            Ok(config.clone())
        })
        .await
    }

