    pub async fn coding_plan_quota_snapshot(
        &self,
        provider_key: ProviderKey,
        force_refresh: bool,
    ) -> anyhow::Result<Result<CodingPlanQuotaSnapshot, ProviderCommandError>> {
        for _ in 0..3 {
            let target = {
                let providers = self.providers.read().await;
                match coding_plan_quota_target_from_store(&providers, &provider_key) {
                    Ok(target) => target,
                    Err(error) => return Ok(Err(error)),
                }
            };
            self.retain_current_coding_plan_quota_cache(&target.cache_key);

            if target.quota.adapter == CodingPlanQuotaAdapter::Unavailable {
                return Ok(Ok(coding_plan_quota_snapshot(
                    &target,
                    CodingPlanQuotaSource::Contract,
                    CodingPlanQuotaView::unavailable(
                        "this coding plan does not publish an authoritative quota API",
                    ),
                )));
            }

            let now_ms = now_ms_i64();
            if !force_refresh {
                if let Some(view) = self.fresh_coding_plan_quota_cache(&target, now_ms) {
                    return Ok(Ok(coding_plan_quota_snapshot(
                        &target,
                        CodingPlanQuotaSource::FreshCache,
                        view,
                    )));
                }
            }

            let refresh_flight = self.coding_plan_quota_refresh_flight(&target.cache_key);
            let (refresh_guard, waited) = match Arc::clone(&refresh_flight.gate).try_lock_owned() {
                Ok(guard) => (guard, false),
                Err(_) => (Arc::clone(&refresh_flight.gate).lock_owned().await, true),
            };
            if waited {
                let current = {
                    let providers = self.providers.read().await;
                    match coding_plan_quota_target_from_store(&providers, &provider_key) {
                        Ok(target) => target,
                        Err(error) => return Ok(Err(error)),
                    }
                };
                if current.cache_key != target.cache_key {
                    drop(refresh_guard);
                    continue;
                }
                if let Some(result) = refresh_flight.completed_result() {
                    return Ok(Ok(coding_plan_quota_snapshot(
                        &target,
                        result.source,
                        result.quota,
                    )));
                }
            } else {
                refresh_flight.clear_result();
            }

            let credentials = {
                let providers = self.providers.read().await;
                let current = match coding_plan_quota_target_from_store(&providers, &provider_key) {
                    Ok(target) => target,
                    Err(error) => return Ok(Err(error)),
                };
                if current.cache_key != target.cache_key {
                    drop(refresh_guard);
                    continue;
                }
                match coding_plan_quota_credentials_from_store(&providers, &provider_key, &current)?
                {
                    Ok(credentials) => credentials,
                    Err(reason) => {
                        self.invalidate_coding_plan_quota_cache(&target.cache_key);
                        let view = CodingPlanQuotaView::unknown(reason);
                        refresh_flight.complete(CodingPlanQuotaSource::Contract, view.clone());
                        return Ok(Ok(coding_plan_quota_snapshot(
                            &target,
                            CodingPlanQuotaSource::Contract,
                            view,
                        )));
                    }
                }
            };

            if !force_refresh || waited {
                if let Some(view) = self.fresh_coding_plan_quota_cache(&target, now_ms_i64()) {
                    return Ok(Ok(coding_plan_quota_snapshot(
                        &target,
                        CodingPlanQuotaSource::FreshCache,
                        view,
                    )));
                }
            }

            let observed_at_ms = now_ms_i64();
            let result = fetch_coding_plan_quota(
                &self.coding_plan_quota_http_client,
                &target.quota,
                &credentials,
                observed_at_ms,
            )
            .await;

            let current = {
                let providers = self.providers.read().await;
                match coding_plan_quota_target_from_store(&providers, &provider_key) {
                    Ok(target) => target,
                    Err(error) => return Ok(Err(error)),
                }
            };
            if current.cache_key != target.cache_key {
                drop(refresh_guard);
                continue;
            }

            let (source, view) = match result {
                Ok(view) => {
                    self.cache_supported_coding_plan_quota(target.cache_key.clone(), view.clone())?;
                    (CodingPlanQuotaSource::Live, view)
                }
                Err(error) if error.is_transient() => {
                    let now_ms = now_ms_i64();
                    if let Some(view) =
                        self.stale_coding_plan_quota_cache(&target, now_ms, error.public_message())
                    {
                        (CodingPlanQuotaSource::StaleCache, view)
                    } else {
                        (
                            CodingPlanQuotaSource::Live,
                            CodingPlanQuotaView::unknown(error.public_message()),
                        )
                    }
                }
                Err(error) => {
                    self.invalidate_coding_plan_quota_cache(&target.cache_key);
                    (
                        CodingPlanQuotaSource::Live,
                        CodingPlanQuotaView::unknown(error.public_message()),
                    )
                }
            };
            refresh_flight.complete(source, view.clone());
            return Ok(Ok(coding_plan_quota_snapshot(&target, source, view)));
        }

        Ok(Err(ProviderCommandError::Conflict {
            code: "provider_runtime_changed",
            message: "Provider runtime changed repeatedly while refreshing coding-plan quota"
                .to_string(),
        }))
    }

    fn coding_plan_quota_refresh_flight(
        &self,
        key: &CodingPlanQuotaCacheKey,
    ) -> Arc<CodingPlanQuotaRefreshFlight> {
        let mut refreshes = self
            .coding_plan_quota_refreshes
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        refreshes.retain(|_, refresh| refresh.strong_count() > 0);
        if let Some(refresh) = refreshes.get(key).and_then(Weak::upgrade) {
            return refresh;
        }
        let refresh = Arc::new(CodingPlanQuotaRefreshFlight::default());
        refreshes.insert(key.clone(), Arc::downgrade(&refresh));
        refresh
    }

    fn retain_current_coding_plan_quota_cache(&self, key: &CodingPlanQuotaCacheKey) {
        self.coding_plan_quota_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .retain_current(key);
    }

    fn fresh_coding_plan_quota_cache(
        &self,
        target: &CodingPlanQuotaTarget,
        now_ms: i64,
    ) -> Option<CodingPlanQuotaView> {
        self.coding_plan_quota_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .fresh(&target.cache_key, now_ms, target.quota.cache_ttl_ms)
    }

    fn stale_coding_plan_quota_cache(
        &self,
        target: &CodingPlanQuotaTarget,
        now_ms: i64,
        reason: &str,
    ) -> Option<CodingPlanQuotaView> {
        self.coding_plan_quota_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .stale(
                &target.cache_key,
                now_ms,
                target.quota.cache_ttl_ms,
                target.quota.stale_ttl_ms,
                reason,
            )
    }

    fn cache_supported_coding_plan_quota(
        &self,
        key: CodingPlanQuotaCacheKey,
        view: CodingPlanQuotaView,
    ) -> anyhow::Result<()> {
        self.coding_plan_quota_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .insert_supported(key, view)
    }

    fn invalidate_coding_plan_quota_cache(&self, key: &CodingPlanQuotaCacheKey) {
        self.coding_plan_quota_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .invalidate(key);
    }

    fn ollama_cloud_share_projection_for_provider(
        &self,
        providers: &ProviderStore,
        app: AppKind,
        provider_id: &str,
        now_ms: i64,
    ) -> Option<OllamaCloudShareProjection> {
        let provider_key = ProviderKey::new(app, provider_id.to_string()).ok()?;
        let target = ollama_cloud_target_from_store(providers, &provider_key).ok()?;
        let cache = self
            .ollama_cloud_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let account = cache.stale_account(&target.cache_key, now_ms);
        let usage = cache.stale_usage(&target.cache_key, now_ms);
        ollama_cloud_share_projection(account.as_ref(), usage.as_ref())
    }

    fn apply_ollama_cloud_share_projections(
        &self,
        descriptor: &mut ShareDescriptor,
        share: &Share,
        providers: &ProviderStore,
    ) {
        let now_ms = now_ms_i64();
        let bindings = descriptor
            .bindings
            .iter()
            .map(|(app, provider_id)| (*app, provider_id.clone()))
            .collect::<Vec<_>>();
        for (app, provider_id) in bindings {
            let Some(projection) = self.ollama_cloud_share_projection_for_provider(
                providers,
                app,
                &provider_id,
                now_ms,
            ) else {
                continue;
            };
            let runtime = match app {
                AppKind::Claude => descriptor.app_runtimes.claude.as_mut(),
                AppKind::Codex => descriptor.app_runtimes.codex.as_mut(),
                AppKind::Gemini => descriptor.app_runtimes.gemini.as_mut(),
            };
            if let Some(runtime) = runtime {
                apply_ollama_projection_to_upstream(runtime, &projection);
            }
            let app_providers = match app {
                AppKind::Claude => &mut descriptor.app_providers.claude,
                AppKind::Codex => &mut descriptor.app_providers.codex,
                AppKind::Gemini => &mut descriptor.app_providers.gemini,
            };
            if let Some(provider) = app_providers
                .iter_mut()
                .find(|provider| provider.id == provider_id)
            {
                apply_ollama_projection_to_app_provider(provider, &projection);
            }
            if share.app == app {
                if let Some(provider) = descriptor.upstream_provider.as_mut() {
                    apply_ollama_projection_to_upstream(provider, &projection);
                }
            }
        }
    }

    /// Builds the descriptor fields returned by the Router's periodic runtime refresh.
    /// The Router replaces its stored app runtimes/providers with this response, so
    /// memory-only display projections must be applied on every refresh.
    pub(crate) fn share_router_runtime_descriptor(
        &self,
        share: &Share,
        providers: &ProviderStore,
        accounts: &AccountStore,
        usage: &UsageStore,
    ) -> ShareDescriptor {
        let mut descriptor = descriptor_for_share_with_accounts_and_usage(
            share,
            providers,
            Some(accounts),
            Some(usage),
        );
        self.apply_ollama_cloud_share_projections(&mut descriptor, share, providers);
        descriptor
    }

    async fn ollama_cloud_share_ids_for_cache_key(
        &self,
        cache_key: &OllamaCloudCacheKey,
    ) -> Vec<String> {
        let providers = self.providers.read().await;
        let provider_keys = providers
            .providers
            .iter()
            .filter_map(|provider| {
                let provider_key =
                    ProviderKey::new(provider.app, provider.provider.id.clone()).ok()?;
                let target = ollama_cloud_target_from_store(&providers, &provider_key).ok()?;
                (target.cache_key == *cache_key).then_some(provider_key)
            })
            .collect::<Vec<_>>();
        drop(providers);
        let shares = self.shares.read().await;
        provider_keys
            .iter()
            .flat_map(|provider_key| {
                shares.share_ids_for_provider(provider_key.app, &provider_key.provider_id)
            })
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect()
    }

    fn schedule_ollama_cloud_share_projection_sync(
        self: &Arc<Self>,
        cache_key: OllamaCloudCacheKey,
    ) {
        let state = Arc::clone(self);
        tokio::spawn(async move {
            if !state
                .config_snapshot()
                .await
                .has_registered_router_identity()
            {
                return;
            }
            let share_ids = state.ollama_cloud_share_ids_for_cache_key(&cache_key).await;
            if share_ids.is_empty() {
                return;
            }
            if let Err(error) = sync_shares_to_router_with_policy(&state, &share_ids, true).await {
                tracing::warn!(
                    share_count = share_ids.len(),
                    %error,
                    "Ollama account display projection sync to Router failed"
                );
            }
        });
    }

    pub async fn ollama_cloud_snapshot(
        self: &Arc<Self>,
        provider_key: ProviderKey,
        force_refresh: bool,
    ) -> anyhow::Result<Result<OllamaCloudSnapshot, ProviderCommandError>> {
        for _ in 0..3 {
            let target = {
                let providers = self.providers.read().await;
                match ollama_cloud_target_from_store(&providers, &provider_key) {
                    Ok(target) => target,
                    Err(error) => return Ok(Err(error)),
                }
            };
            self.retain_current_ollama_cloud_cache(&target.cache_key);

            if !force_refresh {
                if let Some((account, usage)) =
                    self.fresh_ollama_cloud_sections(&target.cache_key, now_ms_i64())
                {
                    return Ok(Ok(ollama_cloud_snapshot(
                        &target,
                        OllamaCloudSnapshotSource::FreshCache,
                        account,
                        usage,
                    )));
                }
            }

            let refresh_flight = self.ollama_cloud_refresh_flight(&target.cache_key);
            let (refresh_guard, waited) = match Arc::clone(&refresh_flight.gate).try_lock_owned() {
                Ok(guard) => (guard, false),
                Err(_) => (Arc::clone(&refresh_flight.gate).lock_owned().await, true),
            };
            if waited {
                let current = {
                    let providers = self.providers.read().await;
                    match ollama_cloud_target_from_store(&providers, &provider_key) {
                        Ok(target) => target,
                        Err(error) => return Ok(Err(error)),
                    }
                };
                if current.cache_key != target.cache_key {
                    drop(refresh_guard);
                    continue;
                }
                if let Some(result) = refresh_flight.completed_result() {
                    return Ok(Ok(ollama_cloud_snapshot(
                        &current,
                        result.source,
                        result.account,
                        result.usage,
                    )));
                }
            } else {
                refresh_flight.clear_result();
            }

            let credentials = {
                let providers = self.providers.read().await;
                let current = match ollama_cloud_target_from_store(&providers, &provider_key) {
                    Ok(target) => target,
                    Err(error) => return Ok(Err(error)),
                };
                if current.cache_key != target.cache_key {
                    drop(refresh_guard);
                    continue;
                }
                match ollama_cloud_credentials_from_store(&providers, &current)? {
                    Ok(credentials) => credentials,
                    Err(reason) => {
                        self.clear_ollama_cloud_cache(&target.cache_key);
                        let account = OllamaCloudSection::unconfigured(reason.clone());
                        let usage = OllamaCloudSection::unconfigured(reason);
                        refresh_flight.complete(
                            OllamaCloudSnapshotSource::Configuration,
                            account.clone(),
                            usage.clone(),
                        );
                        let snapshot = ollama_cloud_snapshot(
                            &current,
                            OllamaCloudSnapshotSource::Configuration,
                            account,
                            usage,
                        );
                        self.schedule_ollama_cloud_share_projection_sync(target.cache_key.clone());
                        return Ok(Ok(snapshot));
                    }
                }
            };

            if !force_refresh || waited {
                if let Some((account, usage)) =
                    self.fresh_ollama_cloud_sections(&target.cache_key, now_ms_i64())
                {
                    return Ok(Ok(ollama_cloud_snapshot(
                        &target,
                        OllamaCloudSnapshotSource::FreshCache,
                        account,
                        usage,
                    )));
                }
            }

            let client = self.ollama_cloud_client.read().await.clone();
            let result = client.fetch(&credentials).await;
            let current = {
                let providers = self.providers.read().await;
                match ollama_cloud_target_from_store(&providers, &provider_key) {
                    Ok(target) => target,
                    Err(error) => return Ok(Err(error)),
                }
            };
            if current.cache_key != target.cache_key {
                drop(refresh_guard);
                continue;
            }

            if result
                .account
                .as_ref()
                .err()
                .is_some_and(|error| error.kind == OllamaCloudErrorKind::Authentication)
                || result
                    .usage
                    .as_ref()
                    .err()
                    .is_some_and(|error| error.kind == OllamaCloudErrorKind::Authentication)
            {
                self.clear_ollama_cloud_cache(&target.cache_key);
            }
            let observed_at_ms = now_ms_i64();
            let account = self.ollama_cloud_account_section(
                &target.cache_key,
                result.account,
                observed_at_ms,
            );
            let usage =
                self.ollama_cloud_usage_section(&target.cache_key, result.usage, observed_at_ms);
            let source = if matches!(account.state, OllamaCloudSectionState::Stale)
                || matches!(usage.state, OllamaCloudSectionState::Stale)
            {
                OllamaCloudSnapshotSource::StaleCache
            } else {
                OllamaCloudSnapshotSource::Live
            };
            refresh_flight.complete(source, account.clone(), usage.clone());
            let snapshot = ollama_cloud_snapshot(&current, source, account, usage);
            self.schedule_ollama_cloud_share_projection_sync(target.cache_key.clone());
            return Ok(Ok(snapshot));
        }

        Ok(Err(ProviderCommandError::Conflict {
            code: "provider_credential_changed",
            message:
                "Provider credential changed repeatedly while refreshing Ollama account information"
                    .to_string(),
        }))
    }

    fn refresh_ollama_cloud_after_provider_commit(self: &Arc<Self>, provider_key: ProviderKey) {
        let state = Arc::clone(self);
        tokio::spawn(async move {
            match state
                .ollama_cloud_snapshot(provider_key.clone(), true)
                .await
            {
                Ok(Ok(_)) | Ok(Err(ProviderCommandError::NotFound)) => {}
                Ok(Err(error)) => tracing::debug!(
                    app = provider_key.app.as_str(),
                    provider_id = %provider_key.provider_id,
                    error = %error,
                    "saved Provider does not expose Ollama account information"
                ),
                Err(error) => tracing::warn!(
                    app = provider_key.app.as_str(),
                    provider_id = %provider_key.provider_id,
                    error = %error,
                    "Ollama account refresh after Provider save failed"
                ),
            }
        });
    }

    fn ollama_cloud_refresh_flight(
        &self,
        key: &OllamaCloudCacheKey,
    ) -> Arc<OllamaCloudRefreshFlight> {
        let mut refreshes = self
            .ollama_cloud_refreshes
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        refreshes.retain(|_, refresh| refresh.strong_count() > 0);
        if let Some(refresh) = refreshes.get(key).and_then(Weak::upgrade) {
            return refresh;
        }
        let refresh = Arc::new(OllamaCloudRefreshFlight::default());
        refreshes.insert(key.clone(), Arc::downgrade(&refresh));
        refresh
    }

    fn fresh_ollama_cloud_sections(
        &self,
        key: &OllamaCloudCacheKey,
        now_ms: i64,
    ) -> Option<(
        OllamaCloudSection<OllamaCloudAccountView>,
        OllamaCloudSection<OllamaCloudUsageView>,
    )> {
        let cache = self
            .ollama_cloud_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let account = cache.fresh_account(key, now_ms)?;
        let usage = cache.fresh_usage(key, now_ms)?;
        Some((
            OllamaCloudSection::available(account.data, account.observed_at_ms),
            OllamaCloudSection::available(usage.data, usage.observed_at_ms),
        ))
    }

    fn ollama_cloud_account_section(
        &self,
        key: &OllamaCloudCacheKey,
        result: Result<OllamaCloudAccountView, OllamaCloudFetchError>,
        observed_at_ms: i64,
    ) -> OllamaCloudSection<OllamaCloudAccountView> {
        let mut cache = self
            .ollama_cloud_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        match result {
            Ok(account) => {
                cache.insert_account(key.clone(), account.clone(), observed_at_ms);
                OllamaCloudSection::available(account, observed_at_ms)
            }
            Err(error) => {
                let stale = error
                    .permits_stale()
                    .then(|| cache.stale_account(key, observed_at_ms))
                    .flatten();
                if let Some(stale) = stale {
                    OllamaCloudSection::stale(
                        stale.data,
                        stale.observed_at_ms,
                        error.kind,
                        error.public_message(),
                        error.retry_after_ms,
                    )
                } else {
                    cache.remove_account(key);
                    OllamaCloudSection::error(
                        error.kind,
                        error.public_message(),
                        error.retry_after_ms,
                    )
                }
            }
        }
    }

    fn ollama_cloud_usage_section(
        &self,
        key: &OllamaCloudCacheKey,
        result: Result<OllamaCloudUsageView, OllamaCloudFetchError>,
        observed_at_ms: i64,
    ) -> OllamaCloudSection<OllamaCloudUsageView> {
        let mut cache = self
            .ollama_cloud_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        match result {
            Ok(usage) => {
                cache.insert_usage(key.clone(), usage.clone(), observed_at_ms);
                OllamaCloudSection::available(usage, observed_at_ms)
            }
            Err(error) => {
                let stale = error
                    .permits_stale()
                    .then(|| cache.stale_usage(key, observed_at_ms))
                    .flatten();
                if let Some(stale) = stale {
                    OllamaCloudSection::stale(
                        stale.data,
                        stale.observed_at_ms,
                        error.kind,
                        error.public_message(),
                        error.retry_after_ms,
                    )
                } else {
                    cache.remove_usage(key);
                    OllamaCloudSection::error(
                        error.kind,
                        error.public_message(),
                        error.retry_after_ms,
                    )
                }
            }
        }
    }

    fn retain_current_ollama_cloud_cache(&self, key: &OllamaCloudCacheKey) {
        self.ollama_cloud_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .retain_current(key);
    }

    fn clear_ollama_cloud_cache(&self, key: &OllamaCloudCacheKey) {
        let mut cache = self
            .ollama_cloud_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        cache.remove_account(key);
        cache.remove_usage(key);
    }

