    #[cfg(test)]
    pub(crate) async fn override_provider_runtime_endpoint_for_test(
        &self,
        app: AppKind,
        provider_id: &str,
        endpoint: String,
    ) -> anyhow::Result<()> {
        let parsed = url::Url::parse(&endpoint).context("parse test Provider endpoint")?;
        let host_is_loopback = parsed.host_str().is_some_and(|host| {
            host.eq_ignore_ascii_case("localhost")
                || host
                    .parse::<std::net::IpAddr>()
                    .is_ok_and(|address| address.is_loopback())
        });
        if parsed.scheme() != "http"
            || !host_is_loopback
            || !parsed.username().is_empty()
            || parsed.password().is_some()
            || parsed.query().is_some()
            || parsed.fragment().is_some()
        {
            anyhow::bail!("test Provider endpoint must be a credential-free loopback HTTP URL");
        }

        let mut providers = self.providers.write().await;
        let accounts = self.accounts.read().await;
        let stored = providers
            .providers
            .iter_mut()
            .find(|stored| stored.app == app && stored.provider.id == provider_id)
            .with_context(|| format!("test Provider not found: {}/{provider_id}", app.as_str()))?;
        if !stored.provider.settings_config.is_object() {
            stored.provider.settings_config = serde_json::json!({});
        }
        stored
            .provider
            .settings_config
            .as_object_mut()
            .expect("test Provider settingsConfig object")
            .insert(
                "testRuntimeEndpoint".to_string(),
                serde_json::Value::String(endpoint),
            );
        providers
            .rebuild_runtime_index(&accounts)
            .context("rebuild Provider runtime index for test endpoint")?;
        Ok(())
    }

    pub async fn mutate_providers_immediate_if_changed<R>(
        self: &Arc<Self>,
        mutate: impl FnOnce(&mut ProviderStore) -> (R, bool) + Send + 'static,
    ) -> anyhow::Result<R>
    where
        R: Send + 'static,
    {
        self.commit_provider_change(move |providers| {
            Ok::<_, std::convert::Infallible>(mutate(providers))
        })
        .await?
        .map_err(|never| match never {})
    }

    pub async fn try_mutate_providers_immediate<R, E>(
        self: &Arc<Self>,
        mutate: impl FnOnce(&mut ProviderStore) -> Result<R, E> + Send + 'static,
    ) -> anyhow::Result<Result<R, E>>
    where
        R: Send + 'static,
        E: Send + 'static,
    {
        self.commit_provider_change(move |providers| mutate(providers).map(|result| (result, true)))
            .await
    }

    pub async fn try_mutate_providers_immediate_if_changed<R, E>(
        self: &Arc<Self>,
        mutate: impl FnOnce(&mut ProviderStore) -> Result<(R, bool), E> + Send + 'static,
    ) -> anyhow::Result<Result<R, E>>
    where
        R: Send + 'static,
        E: Send + 'static,
    {
        self.commit_provider_change(mutate).await
    }

    async fn commit_provider_change<R, E>(
        self: &Arc<Self>,
        mutate: impl FnOnce(&mut ProviderStore) -> Result<(R, bool), E> + Send + 'static,
    ) -> anyhow::Result<Result<R, E>>
    where
        R: Send + 'static,
        E: Send + 'static,
    {
        self.commit_provider_change_with_reference_guard(None, mutate)
            .await
    }

    async fn commit_provider_change_under_reference_guard<R, E>(
        self: &Arc<Self>,
        reference_guard: tokio::sync::OwnedMutexGuard<()>,
        mutate: impl FnOnce(&mut ProviderStore) -> Result<(R, bool), E> + Send + 'static,
    ) -> anyhow::Result<Result<R, E>>
    where
        R: Send + 'static,
        E: Send + 'static,
    {
        self.commit_provider_change_with_reference_guard(Some(reference_guard), mutate)
            .await
    }

    async fn commit_provider_change_with_reference_guard<R, E>(
        self: &Arc<Self>,
        reference_guard: Option<tokio::sync::OwnedMutexGuard<()>>,
        mutate: impl FnOnce(&mut ProviderStore) -> Result<(R, bool), E> + Send + 'static,
    ) -> anyhow::Result<Result<R, E>>
    where
        R: Send + 'static,
        E: Send + 'static,
    {
        let state = Arc::clone(self);
        let (result_tx, result_rx) = tokio::sync::oneshot::channel();
        tokio::spawn(async move {
            let _references = match reference_guard {
                Some(reference_guard) => reference_guard,
                None => state.reference_mutations.clone().lock_owned().await,
            };
            let result = state.commit_provider_change_owned(mutate).await;
            let _ = result_tx.send(result);
        });
        result_rx
            .await
            .context("provider commit coordinator stopped before reporting a result")?
    }

    async fn commit_provider_change_owned<R, E>(
        self: &Arc<Self>,
        mutate: impl FnOnce(&mut ProviderStore) -> Result<(R, bool), E> + Send + 'static,
    ) -> anyhow::Result<Result<R, E>>
    where
        R: Send + 'static,
        E: Send + 'static,
    {
        let _commit = self.provider_commits.lock().await;
        let _workspace_transaction = self.codex_workspace_rebind_transactions.lock().await;
        self.recover_pending_codex_workspace_rebind_transaction("Provider commit")?;
        let current = self.providers.read().await.clone();
        let mut candidate = current
            .materialized_clone()
            .context("materialize Provider credentials for commit")?;
        let (result, changed) = match mutate(&mut candidate) {
            Ok(result) => result,
            Err(error) => return Ok(Err(error)),
        };
        if !changed {
            return Ok(Ok(result));
        }
        candidate.validate_for_commit()?;
        let accounts = self.accounts.read().await.clone();
        let shares = self.shares.read().await.clone();
        crate::domain::sharing::subscription_identity::validate_ordinary_subscription_reference_change(
            &current, &candidate, &accounts, &shares,
        )
        .map_err(|error| anyhow::anyhow!("[{}] {error}", error.code()))?;
        candidate
            .rebuild_runtime_index(&accounts)
            .context("compile Provider runtime index before commit")?;
        let changed_projection_keys = provider_share_projection_changes(&current, &candidate);
        let changed_capacity_source_keys =
            provider_capacity_source_changes(&current, &candidate, &accounts)
                .context("detect Provider capacity source changes")?;
        let affected_capacity_share_ids = changed_projection_keys
            .iter()
            .chain(changed_capacity_source_keys.iter())
            .flat_map(|(app, provider_id)| shares.share_ids_for_provider(*app, provider_id))
            .collect::<BTreeSet<_>>();
        candidate
            .seal_for_commit(&self.config_dir)
            .context("seal Provider credentials before commit")?;
        candidate
            .rebuild_runtime_index(&accounts)
            .context("compile sealed Provider runtime index before commit")?;
        let previous_ollama_cloud_cache_keys = ollama_cloud_cache_keys_from_store(&current);
        let ollama_cloud_cache_keys = ollama_cloud_cache_keys_from_store(&candidate);
        let ollama_cloud_refresh_keys = ollama_cloud_cache_keys
            .difference(&previous_ollama_cloud_cache_keys)
            .map(|key| key.credential_source_key.clone())
            .collect::<Vec<_>>();
        let capacity_pool_root_key = crate::infra::credentials::load_root_key(&self.config_dir)
            .context("resolve key for Share capacity pools")?;
        let mut projected_shares = shares.clone();
        let changed_capacity_share_ids = projected_shares
            .refresh_capacity_pool_ids_for_shares(
                &affected_capacity_share_ids,
                &candidate,
                &accounts,
                &capacity_pool_root_key.key,
            )
            .map_err(|error| anyhow::anyhow!("[{}] {error}", error.code()))?;
        let capacity_pool_updates = changed_capacity_share_ids
            .iter()
            .filter_map(|share_id| {
                projected_shares
                    .get(share_id)
                    .map(|share| (share_id.clone(), share.capacity_pool_id.clone()))
            })
            .collect::<BTreeMap<_, _>>();

        #[cfg(test)]
        {
            let delay_ms = self
                .provider_commit_delay_ms
                .load(std::sync::atomic::Ordering::Relaxed);
            if delay_ms > 0 {
                sleep(Duration::from_millis(delay_ms)).await;
            }
        }

        let config_dir = self.config_dir.clone();
        let persisted_candidate = candidate.clone();
        let persist_result =
            tokio::task::spawn_blocking(move || persisted_candidate.save(&config_dir))
                .await
                .context("provider persistence task panicked")?;

        if let Err(error) = persist_result {
            // rename is the commit point. A directory-fsync error can be reported after the
            // candidate is already authoritative on disk, so reconcile before deciding.
            let on_disk = ProviderStore::load_runtime_or_default(&self.config_dir);
            let candidate_json = serde_json::to_value(&candidate);
            let disk_matches = on_disk
                .as_ref()
                .ok()
                .and_then(|store| serde_json::to_value(store).ok())
                .zip(candidate_json.ok())
                .is_some_and(|(disk, expected)| disk == expected);
            if !disk_matches {
                return Err(error);
            }
            tracing::warn!(
                error = %error,
                "provider file reached the commit point despite a persistence error; reconciled live state"
            );
        }

        *self.providers.write().await = candidate;
        self.ollama_cloud_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .retain_keys(&ollama_cloud_cache_keys);
        if self.ollama_cloud_post_commit_refresh_is_enabled() {
            for provider_key in ollama_cloud_refresh_keys {
                self.refresh_ollama_cloud_after_provider_commit(provider_key);
            }
        }
        let published_providers = self.providers.read().await.clone();
        let usage = self.usage.read().await.clone();
        let (changed_capacity_share_ids, changed_runtime_share_ids) = self
            .apply_share_provider_updates_under_provider_commit(
                &capacity_pool_updates,
                &changed_projection_keys,
                &published_providers,
                &accounts,
                &usage,
            )
            .await?;
        if let Err(error) = self.prune_provider_health_snapshots().await {
            tracing::warn!(
                %error,
                "Provider commit succeeded but stale health snapshots could not be pruned"
            );
        }
        if !changed_runtime_share_ids.is_empty() || !changed_capacity_share_ids.is_empty() {
            self.emit_event(
                ServerEvent::new("share.changed", "share")
                    .message("provider_runtime_metadata_updated"),
            );
            let mut share_ids = {
                let shares = self.shares.read().await;
                changed_projection_keys
                    .iter()
                    .flat_map(|(app, provider_id)| shares.share_ids_for_provider(*app, provider_id))
                    .collect::<BTreeSet<_>>()
                    .into_iter()
                    .collect::<Vec<_>>()
            };
            share_ids.extend(changed_capacity_share_ids);
            share_ids.extend(changed_runtime_share_ids.iter().cloned());
            share_ids.sort();
            share_ids.dedup();
            let force_router_sync = !changed_runtime_share_ids.is_empty();
            if !share_ids.is_empty()
                && self
                    .config_snapshot()
                    .await
                    .has_registered_router_identity()
            {
                let state = Arc::clone(self);
                tokio::spawn(async move {
                    if let Err(error) =
                        sync_shares_to_router_with_policy(&state, &share_ids, force_router_sync)
                            .await
                    {
                        tracing::warn!(
                            share_count = share_ids.len(),
                            %error,
                            "Provider commit Share descriptor reconcile remains pending"
                        );
                    }
                });
            }
        }
        Ok(Ok(result))
    }

    async fn apply_share_provider_updates_under_provider_commit(
        &self,
        capacity_pool_updates: &BTreeMap<String, String>,
        runtime_provider_keys: &BTreeSet<(AppKind, String)>,
        providers: &ProviderStore,
        accounts: &AccountStore,
        usage: &UsageStore,
    ) -> anyhow::Result<(Vec<String>, Vec<String>)> {
        if capacity_pool_updates.is_empty() && runtime_provider_keys.is_empty() {
            return Ok((Vec::new(), Vec::new()));
        }
        let _commit = self.shares_persistence.gate.lock().await;
        let mut candidate = self.shares.read().await.clone();
        let capacity_ids = candidate.apply_capacity_pool_ids(capacity_pool_updates);
        let runtime_ids = candidate.reconcile_runtime_snapshots_for_providers(
            runtime_provider_keys,
            providers,
            Some(accounts),
            usage,
        );
        if capacity_ids.is_empty() && runtime_ids.is_empty() {
            return Ok((capacity_ids, runtime_ids));
        }
        persist_state_snapshot(&self.config_dir, candidate.clone()).await?;
        *self.shares.write().await = candidate;
        self.shares_persistence.mark_published();
        Ok((capacity_ids, runtime_ids))
    }

    pub async fn save_accounts(&self) -> anyhow::Result<()> {
        let _workspace_transaction = self.codex_workspace_rebind_transactions.lock().await;
        self.recover_pending_codex_workspace_rebind_transaction("Accounts save")?;
        let _commit = self.accounts_persistence.gate.lock().await;
        let snapshot = self.accounts.read().await.clone();
        persist_state_snapshot(&self.config_dir, snapshot).await
    }

    pub fn credential_persistence_degraded(&self) -> bool {
        self.credential_persistence_state
            .load(std::sync::atomic::Ordering::Acquire)
            & 1
            != 0
    }

    fn mark_credential_persistence_degraded(&self) {
        let mut current = self
            .credential_persistence_state
            .load(std::sync::atomic::Ordering::Acquire);
        loop {
            let next = current.wrapping_add(2) | 1;
            match self.credential_persistence_state.compare_exchange_weak(
                current,
                next,
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
            ) {
                Ok(_) => {
                    if current & 1 == 0 {
                        let mut event = AuditEvent::new("observability.component.degraded");
                        event.component = Some("credential_storage".to_string());
                        event.failure_kind = Some("durable_write".to_string());
                        event.retry_decision = Some("retry".to_string());
                        event.outcome = Some("degraded".to_string());
                        event.retryable = Some(true);
                        self.emit_audit_event_best_effort(event);
                    }
                    break;
                }
                Err(actual) => current = actual,
            }
        }
        crate::metrics::set_credential_persistence_degraded(true);
    }

    fn clear_credential_persistence_degraded_if_unchanged(&self, observed: u64) -> bool {
        if observed & 1 == 0 {
            return !self.credential_persistence_degraded();
        }
        match self.credential_persistence_state.compare_exchange(
            observed,
            observed & !1,
            std::sync::atomic::Ordering::AcqRel,
            std::sync::atomic::Ordering::Acquire,
        ) {
            Ok(_) => {
                crate::metrics::set_credential_persistence_degraded(false);
                let mut event = AuditEvent::new("observability.component.recovered");
                event.component = Some("credential_storage".to_string());
                event.failure_kind = Some("durable_write".to_string());
                event.retry_decision = Some("resume".to_string());
                event.outcome = Some("recovered".to_string());
                event.retryable = Some(false);
                self.emit_audit_event_best_effort(event);
                true
            }
            Err(actual) => actual & 1 == 0,
        }
    }

    fn pending_native_refresh_receipt(
        &self,
        account: &Account,
    ) -> anyhow::Result<Option<NativeRefreshPendingReceipt>> {
        let key = native_refresh_pending_key(account);
        let path = native_refresh_pending_path(&self.config_dir, account);
        let mut journal = self
            .native_refresh_receipt_journal
            .lock()
            .map_err(|_| anyhow::anyhow!("native refresh receipt journal lock poisoned"))?;
        let pending = match journal.pending.get(&key).cloned() {
            Some(pending) => Some(pending),
            None => match load_native_refresh_pending_receipt(&self.config_dir, account) {
                Ok(pending) => {
                    journal.unresolved_loads.remove(&path);
                    pending
                }
                Err(error) if !native_refresh_pending_load_has_io_error(&error) => {
                    quarantine_native_refresh_pending_receipt_path(&self.config_dir, &path)
                        .with_context(|| {
                            format!(
                                "quarantine unreadable OAuth refresh receipt {} after: {error:#}",
                                path.display()
                            )
                        })?;
                    journal.unresolved_loads.remove(&path);
                    anyhow::bail!(
                        "quarantined unreadable OAuth refresh receipt {}: {error:#}",
                        path.display()
                    );
                }
                Err(error) => {
                    journal.unresolved_loads.insert(path.clone());
                    return Err(error);
                }
            },
        };
        let Some(pending) = pending else {
            return Ok(None);
        };
        if !native_refresh_snapshot_matches(account, &pending.expected) {
            quarantine_native_refresh_pending_receipt_path(&self.config_dir, &path)?;
            journal.pending.remove(&key);
            journal.unresolved_loads.remove(&path);
            tracing::warn!(
                account_id = %pending.expected.id,
                provider_type = %pending.expected.provider_type.as_str(),
                "quarantined superseded OAuth refresh receipt"
            );
            return Ok(None);
        }
        journal.pending.insert(key, pending.clone());
        Ok(Some(pending))
    }

    fn remember_native_refresh_pending_receipt(
        self: &Arc<Self>,
        expected: &Account,
        update: &AccountRefreshUpdate,
    ) -> Result<(), AccountRefreshFailure> {
        let pending = NativeRefreshPendingReceipt {
            expected: expected.clone(),
            update: update.clone(),
        };
        let mut journal = self.native_refresh_receipt_journal.lock().map_err(|_| {
            AccountRefreshFailure::bad_gateway("native refresh receipt journal lock is unavailable")
        })?;
        journal
            .pending
            .insert(native_refresh_pending_key(expected), pending);
        if let Err(error) = write_native_refresh_pending_receipt(&self.config_dir, expected, update)
        {
            self.mark_credential_persistence_degraded();
            self.schedule_credential_persistence_retry();
            tracing::error!(
                account_id = %expected.id,
                provider_type = %expected.provider_type.as_str(),
                %error,
                "could not persist OAuth refresh receipt before identity validation"
            );
            return Err(AccountRefreshFailure::bad_gateway(
                "OAuth refresh receipt is waiting for durable persistence",
            ));
        }
        Ok(())
    }

    fn persist_in_memory_native_refresh_receipts(&self) -> anyhow::Result<()> {
        let mut journal = self
            .native_refresh_receipt_journal
            .lock()
            .map_err(|_| anyhow::anyhow!("native refresh receipt journal lock poisoned"))?;
        let unresolved = journal.unresolved_loads.iter().cloned().collect::<Vec<_>>();
        for path in unresolved {
            match load_native_refresh_pending_receipt_from_path(&self.config_dir, &path) {
                Ok(Some(pending))
                    if native_refresh_pending_path(&self.config_dir, &pending.expected) == path =>
                {
                    journal
                        .pending
                        .insert(native_refresh_pending_key(&pending.expected), pending);
                    journal.unresolved_loads.remove(&path);
                }
                Ok(Some(_)) => {
                    quarantine_native_refresh_pending_receipt_path(&self.config_dir, &path)?;
                    journal.unresolved_loads.remove(&path);
                    tracing::warn!(
                        path = %path.display(),
                        "quarantined OAuth refresh receipt stored under the wrong account path"
                    );
                }
                Ok(None) => {
                    journal.unresolved_loads.remove(&path);
                }
                Err(error) if !native_refresh_pending_load_has_io_error(&error) => {
                    quarantine_native_refresh_pending_receipt_path(&self.config_dir, &path)?;
                    journal.unresolved_loads.remove(&path);
                    tracing::warn!(
                        path = %path.display(),
                        %error,
                        "quarantined unreadable OAuth refresh receipt during persistence retry"
                    );
                }
                Err(error) => return Err(error),
            }
        }
        if !journal.unresolved_loads.is_empty() {
            anyhow::bail!(
                "{} OAuth refresh receipt journal(s) remain unreadable",
                journal.unresolved_loads.len()
            );
        }
        for receipt in journal.pending.values() {
            write_native_refresh_pending_receipt(
                &self.config_dir,
                &receipt.expected,
                &receipt.update,
            )?;
        }
        Ok(())
    }

    fn clear_native_refresh_pending_receipt(&self, account: &Account) {
        match self.native_refresh_receipt_journal.lock() {
            Ok(mut journal) => {
                journal.pending.remove(&native_refresh_pending_key(account));
                journal
                    .unresolved_loads
                    .remove(&native_refresh_pending_path(&self.config_dir, account));
                if let Err(error) = remove_native_refresh_pending_receipt(&self.config_dir, account)
                {
                    tracing::warn!(
                        account_id = %account.id,
                        provider_type = %account.provider_type.as_str(),
                        %error,
                        "could not remove committed OAuth refresh receipt"
                    );
                }
            }
            Err(_) => tracing::error!(
                account_id = %account.id,
                provider_type = %account.provider_type.as_str(),
                "native refresh receipt journal lock is unavailable during commit cleanup"
            ),
        }
    }

    fn quarantine_native_refresh_pending_receipt(
        self: &Arc<Self>,
        account: &Account,
        reason: &str,
    ) -> anyhow::Result<()> {
        let key = native_refresh_pending_key(account);
        let path = native_refresh_pending_path(&self.config_dir, account);
        let mut journal = self
            .native_refresh_receipt_journal
            .lock()
            .map_err(|_| anyhow::anyhow!("native refresh receipt journal lock poisoned"))?;
        let pending = journal.pending.get(&key).cloned();
        if let Some(pending) = pending.as_ref() {
            write_native_refresh_pending_receipt(
                &self.config_dir,
                &pending.expected,
                &pending.update,
            )?;
        }
        let quarantined = quarantine_native_refresh_pending_receipt_path(&self.config_dir, &path)?;
        journal.pending.remove(&key);
        journal.unresolved_loads.remove(&path);
        if let Some(path) = quarantined {
            tracing::warn!(
                account_id = %account.id,
                provider_type = %account.provider_type.as_str(),
                quarantine_path = %path.display(),
                reason,
                "quarantined OAuth refresh receipt without activating it"
            );
        }
        Ok(())
    }

    fn handle_native_refresh_receipt_validation_failure(
        self: &Arc<Self>,
        account: &Account,
        error: &AccountRefreshFailure,
    ) -> anyhow::Result<()> {
        if error.retryable {
            return Ok(());
        }
        self.quarantine_native_refresh_pending_receipt(account, &error.message)
    }

    fn report_native_refresh_receipt_handling_error(
        self: &Arc<Self>,
        account: &Account,
        error: anyhow::Error,
    ) {
        self.mark_credential_persistence_degraded();
        self.schedule_credential_persistence_retry();
        tracing::error!(
            account_id = %account.id,
            %error,
            "could not preserve rejected OAuth refresh receipt"
        );
    }

    pub(crate) async fn execute_native_account_refresh_with_recovery(
        self: &Arc<Self>,
        http: &reqwest::Client,
        account: &Account,
        now_ms: i64,
        quota_refresh_interval_ms: i64,
        refresh_guard: &mut crate::domain::accounts::managers::AccountRefreshGuard,
    ) -> Result<AccountRefreshUpdate, AccountRefreshFailure> {
        if let Some(failure) = refresh_guard.coalesced_native_failure_for(account) {
            return Err(AccountRefreshFailure {
                status_code: failure.status_code,
                upstream_status: failure.upstream_status,
                message: failure.message.clone(),
                kind: failure.kind,
                retryable: failure.retryable,
                retry_after_ms: failure.retry_after_ms,
                immediate_relogin: failure.immediate_relogin,
                outcome_unknown: false,
                endpoint_fallback_safe: false,
            });
        }
        let pending = match self.pending_native_refresh_receipt(account) {
            Ok(pending) => pending,
            Err(error) => {
                self.mark_credential_persistence_degraded();
                self.schedule_credential_persistence_retry();
                let result = Err(AccountRefreshFailure::bad_gateway(format!(
                    "load OAuth refresh receipt failed: {error}"
                )));
                record_refresh_flight_failure(refresh_guard, account, &result);
                return result;
            }
        };
        if let Some(pending) = pending {
            let mut result =
                validate_native_account_refresh_receipt(http, account, pending.update).await;
            if let Err(error) = &mut result {
                if error.retryable && error.retry_after_ms.is_none() {
                    error.retry_after_ms = Some(NATIVE_REFRESH_RECEIPT_RETRY_BACKOFF_MS);
                }
            }
            record_refresh_flight_failure(refresh_guard, account, &result);
            if let Err(error) = &result {
                if let Err(handling_error) =
                    self.handle_native_refresh_receipt_validation_failure(account, error)
                {
                    self.report_native_refresh_receipt_handling_error(account, handling_error);
                }
            }
            return result;
        }

        let result = execute_native_account_refresh_client(
            http,
            account,
            now_ms,
            quota_refresh_interval_ms,
            refresh_guard,
            |update| self.remember_native_refresh_pending_receipt(account, update),
        )
        .await;
        if let Err(error) = &result {
            if let Err(handling_error) =
                self.handle_native_refresh_receipt_validation_failure(account, error)
            {
                self.report_native_refresh_receipt_handling_error(account, handling_error);
            }
        }
        result
    }

    pub(crate) async fn commit_native_refresh_success(
        self: &Arc<Self>,
        expected: &Account,
        update: AccountRefreshUpdate,
    ) -> Result<Account, NativeRefreshCommitError> {
        let recovery_update = update.clone();
        let recovery_journal =
            match write_native_refresh_recovery_journal(&self.config_dir, expected, &update) {
                Ok(path) => Some(path),
                Err(error) => {
                    tracing::error!(
                        account_id = %expected.id,
                        provider_type = %expected.provider_type.as_str(),
                        %error,
                        "could not persist OAuth credential recovery journal"
                    );
                    None
                }
            };
        let _references = self.reference_mutations.lock().await;
        let _workspace_transaction = self.codex_workspace_rebind_transactions.lock().await;
        if let Err(error) =
            self.recover_pending_codex_workspace_rebind_transaction("OAuth credential commit")
        {
            drop(_workspace_transaction);
            drop(_references);
            return self
                .recover_native_refresh_credentials(
                    expected,
                    recovery_update,
                    error,
                    false,
                    recovery_journal,
                )
                .await;
        }
        #[cfg(test)]
        if self
            .account_refresh_commit_state_failures
            .fetch_update(
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
                |remaining| remaining.checked_sub(1),
            )
            .is_ok()
        {
            drop(_workspace_transaction);
            drop(_references);
            return self
                .recover_native_refresh_credentials(
                    expected,
                    recovery_update,
                    anyhow::anyhow!("injected OAuth credential commit state failure"),
                    true,
                    recovery_journal,
                )
                .await;
        }

        let _accounts_commit = self.accounts_persistence.gate.lock().await;
        let providers = self.providers.read().await.clone();
        let current = self.accounts.read().await.clone();
        let shares = self.shares.read().await.clone();
        let live = current
            .accounts
            .iter()
            .find(|account| account.id == expected.id)
            .cloned()
            .with_context(|| format!("managed account not found: {}", expected.id))
            .map_err(NativeRefreshCommitError::State)?;
        if !native_refresh_snapshot_matches(&live, expected) {
            tracing::info!(
                account_id = %expected.id,
                provider_type = %expected.provider_type.as_str(),
                expected_auth_generation = expected.auth_identity_generation,
                current_auth_generation = live.auth_identity_generation,
                expected_token_generation = expected.token_refresh_generation,
                current_token_generation = live.token_refresh_generation,
                "discarded superseded OAuth refresh result"
            );
            if let Some(path) = recovery_journal.as_deref() {
                if let Err(error) = remove_native_refresh_recovery_journal(path) {
                    tracing::warn!(%error, "could not remove superseded OAuth refresh journal");
                }
            }
            if let Err(error) = self.quarantine_native_refresh_pending_receipt(
                expected,
                "account credentials changed before refresh commit",
            ) {
                tracing::warn!(%error, "could not quarantine superseded OAuth refresh receipt");
            }
            return Err(NativeRefreshCommitError::Superseded(Box::new(live)));
        }
        let mut candidate = current.clone();
        let mut updated = candidate
            .mark_native_refresh_success(&expected.id, update)
            .with_context(|| format!("managed account not found: {}", expected.id))
            .map_err(NativeRefreshCommitError::State)?;
        if let Err(error) = crate::domain::sharing::subscription_identity::validate_ordinary_account_subscription_change(
                &providers,
                &current,
                &candidate,
                &shares,
            )
        {
            let (recovery_candidate, recovery_account, recovery_scope) =
                native_refresh_recovery_candidate(&current, expected, &recovery_update)
                    .with_context(|| {
                        format!(
                            "managed account credential recovery candidate is unavailable: {}",
                            expected.id
                        )
                    })
                    .map_err(NativeRefreshCommitError::State)?;
            tracing::warn!(
                account_id = %expected.id,
                provider_type = %expected.provider_type.as_str(),
                recovery_scope,
                %error,
                "preserving rotated OAuth credentials without rejected identity metadata"
            );
            candidate = recovery_candidate;
            updated = recovery_account;
        }

        let persistence_state_before_save = self
            .credential_persistence_state
            .load(std::sync::atomic::Ordering::Acquire);
        #[cfg(test)]
        let persist_result = if self
            .account_refresh_persist_failures
            .fetch_update(
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
                |remaining| remaining.checked_sub(1),
            )
            .is_ok()
        {
            Err(anyhow::anyhow!(
                "injected OAuth credential persistence failure"
            ))
        } else {
            persist_state_snapshot(&self.config_dir, candidate.clone()).await
        };
        #[cfg(not(test))]
        let persist_result = persist_state_snapshot(&self.config_dir, candidate.clone()).await;

        // Publish the degraded gate before credentials that failed to persist become visible.
        // A rotating refresh token may already have invalidated the previous token, so the new
        // credentials remain live for the persistence retry but cannot be used for new traffic.
        if persist_result.is_err() {
            self.mark_credential_persistence_degraded();
        }
        *self.accounts.write().await = candidate;
        self.accounts_persistence.mark_published();

        if let Err(error) = persist_result {
            self.schedule_credential_persistence_retry();
            return Err(NativeRefreshCommitError::Persistence(error));
        }

        self.clear_credential_persistence_degraded_if_unchanged(persistence_state_before_save);
        if let Some(path) = recovery_journal.as_deref() {
            if let Err(error) = remove_native_refresh_recovery_journal(path) {
                tracing::warn!(%error, "could not remove committed OAuth refresh journal");
            }
        }
        self.clear_native_refresh_pending_receipt(expected);
        Ok(updated)
    }

    async fn recover_native_refresh_credentials(
        self: &Arc<Self>,
        expected: &Account,
        update: AccountRefreshUpdate,
        state_error: anyhow::Error,
        persistence_allowed: bool,
        recovery_journal: Option<PathBuf>,
    ) -> Result<Account, NativeRefreshCommitError> {
        let _references = self.reference_mutations.lock().await;
        let _workspace_transaction = self.codex_workspace_rebind_transactions.lock().await;
        let _accounts_commit = self.accounts_persistence.gate.lock().await;
        let current = self.accounts.read().await.clone();
        let live = current
            .accounts
            .iter()
            .find(|account| account.id == expected.id)
            .cloned()
            .with_context(|| format!("managed account not found: {}", expected.id))
            .map_err(NativeRefreshCommitError::State)?;
        if !native_refresh_snapshot_matches(&live, expected) {
            tracing::info!(
                account_id = %expected.id,
                provider_type = %expected.provider_type.as_str(),
                "discarded superseded OAuth credential recovery result"
            );
            if let Some(path) = recovery_journal.as_deref() {
                if let Err(error) = remove_native_refresh_recovery_journal(path) {
                    tracing::warn!(%error, "could not remove superseded OAuth refresh journal");
                }
            }
            if let Err(error) = self.quarantine_native_refresh_pending_receipt(
                expected,
                "account credentials changed before refresh recovery",
            ) {
                tracing::warn!(%error, "could not quarantine superseded OAuth refresh receipt");
            }
            return Err(NativeRefreshCommitError::Superseded(Box::new(live)));
        }
        let (candidate, updated, recovery_scope) =
            native_refresh_recovery_candidate(&current, expected, &update)
                .with_context(|| {
                    format!(
                        "managed account credential recovery candidate is unavailable: {}",
                        expected.id
                    )
                })
                .map_err(NativeRefreshCommitError::State)?;
        tracing::warn!(
            account_id = %expected.id,
            provider_type = %expected.provider_type.as_str(),
            recovery_scope,
            error = %state_error,
            "recovering rotated OAuth credentials after local state commit failure"
        );

        let persistence_state_before_save = self
            .credential_persistence_state
            .load(std::sync::atomic::Ordering::Acquire);
        let persist_result = if persistence_allowed {
            persist_state_snapshot(&self.config_dir, candidate.clone()).await
        } else {
            Err(state_error
                .context("rotated OAuth credentials are waiting for local state recovery"))
        };
        if persist_result.is_err() {
            self.mark_credential_persistence_degraded();
        }
        *self.accounts.write().await = candidate;
        self.accounts_persistence.mark_published();

        if let Err(error) = persist_result {
            self.schedule_credential_persistence_retry();
            return Err(NativeRefreshCommitError::Persistence(error));
        }
        self.clear_credential_persistence_degraded_if_unchanged(persistence_state_before_save);
        if let Some(path) = recovery_journal.as_deref() {
            if let Err(error) = remove_native_refresh_recovery_journal(path) {
                tracing::warn!(%error, "could not remove recovered OAuth refresh journal");
            }
        }
        self.clear_native_refresh_pending_receipt(expected);
        Ok(updated)
    }

    pub(crate) async fn commit_native_refresh_failure(
        self: &Arc<Self>,
        expected: &Account,
        message: String,
        kind: crate::domain::accounts::oauth::OAuthErrorKind,
        immediate_relogin: bool,
    ) -> anyhow::Result<Option<Account>> {
        self.commit_native_refresh_failure_state(expected, message, kind, immediate_relogin, None)
            .await
    }

    async fn commit_native_refresh_failure_state(
        self: &Arc<Self>,
        expected: &Account,
        message: String,
        kind: crate::domain::accounts::oauth::OAuthErrorKind,
        immediate_relogin: bool,
        quota_next_refresh_at: Option<i64>,
    ) -> anyhow::Result<Option<Account>> {
        let expected = expected.clone();
        self.mutate_accounts_immediate(move |accounts| {
            let current = accounts
                .accounts
                .iter()
                .find(|account| account.id == expected.id)
                .cloned()?;
            if !native_refresh_snapshot_matches(&current, &expected) {
                tracing::info!(
                    account_id = %expected.id,
                    provider_type = %expected.provider_type.as_str(),
                    "discarded superseded OAuth refresh failure"
                );
                return Some(current);
            }
            let message = accounts
                .accounts
                .iter()
                .find(|account| account.id == expected.id)
                .map(|account| redact_account_error_for_log(account, &message))
                .unwrap_or_else(|| crate::logging::redact_sensitive_text(&message));
            accounts.mark_native_refresh_failure_with_relogin_hint(
                &expected.id,
                message,
                kind,
                immediate_relogin,
            )?;
            let account = accounts
                .accounts
                .iter_mut()
                .find(|account| account.id == expected.id)?;
            if let Some(quota_next_refresh_at) = quota_next_refresh_at {
                account.quota_next_refresh_at = Some(
                    account
                        .quota_next_refresh_at
                        .unwrap_or(quota_next_refresh_at)
                        .max(quota_next_refresh_at),
                );
            }
            Some(account.clone())
        })
        .await
    }

    fn schedule_credential_persistence_retry(self: &Arc<Self>) {
        if self
            .credential_persistence_retry_scheduled
            .swap(true, std::sync::atomic::Ordering::AcqRel)
        {
            return;
        }
        let state = Arc::clone(self);
        tokio::spawn(async move {
            let mut delay = Duration::from_secs(1);
            loop {
                sleep(delay).await;
                if !state.credential_persistence_degraded() {
                    if state.finish_credential_persistence_retry_or_reclaim() {
                        delay = Duration::from_secs(1);
                        continue;
                    }
                    return;
                }
                let observed = state
                    .credential_persistence_state
                    .load(std::sync::atomic::Ordering::Acquire);
                match state
                    .save_accounts()
                    .await
                    .and_then(|()| state.persist_in_memory_native_refresh_receipts())
                {
                    Ok(()) => {
                        let accounts = state.accounts_snapshot().await;
                        if let Err(error) =
                            remove_superseded_native_refresh_journals(&state.config_dir, &accounts)
                        {
                            tracing::warn!(
                                %error,
                                "could not clean OAuth refresh journals after persistence retry"
                            );
                        }
                        if state.clear_credential_persistence_degraded_if_unchanged(observed) {
                            tracing::info!("durably persisted OAuth credentials after retry");
                        }
                        delay = Duration::from_secs(1);
                        if !state.credential_persistence_degraded() {
                            if state.finish_credential_persistence_retry_or_reclaim() {
                                continue;
                            }
                            return;
                        }
                    }
                    Err(error) => {
                        tracing::error!(
                            %error,
                            retry_in_ms = delay.as_millis(),
                            "OAuth credential persistence retry failed"
                        );
                        delay = delay.saturating_mul(2).min(Duration::from_secs(60));
                    }
                }
            }
        });
    }

    fn finish_credential_persistence_retry_or_reclaim(&self) -> bool {
        self.credential_persistence_retry_scheduled
            .store(false, std::sync::atomic::Ordering::Release);
        self.credential_persistence_degraded()
            && !self
                .credential_persistence_retry_scheduled
                .swap(true, std::sync::atomic::Ordering::AcqRel)
    }

