    async fn refresh_managed_account_inner(
        self: &Arc<Self>,
        provider_type: ProviderType,
        account_id: &str,
        expected_auth_identity_generation: Option<u64>,
        force: bool,
        access: ManagedAccountRefreshAccess,
    ) -> Result<(), ManagedAccountRefreshError> {
        let now = crate::infra::time::now_ms() as i64;
        let account = {
            let accounts = self.accounts.read().await;
            ensure_managed_account_refresh_access(&accounts, provider_type, account_id, access)?;
            accounts
                .find_for_provider(provider_type, Some(account_id))
                .cloned()
        };
        let Some(account) = account else {
            return if expected_auth_identity_generation.is_some() {
                Err(ManagedAccountRefreshError::NotFound)
            } else {
                Ok(())
            };
        };
        ensure_account_identity_generation(
            &account,
            provider_type,
            expected_auth_identity_generation,
        )?;
        if !force && !account_needs_native_refresh(&account, now) {
            return Ok(());
        }
        let refresh_generation = (
            account.auth_identity_generation,
            account.token_refresh_generation,
        );
        let key = format!(
            "{}:{}:{}:{}:{}:{}",
            provider_type.as_str(),
            account.id.len(),
            account.id,
            refresh_generation.0,
            refresh_generation.1,
            access.flight_key(),
        );
        let (flight, owner) = self.managed_account_refreshes.flight(key.clone())?;
        if owner {
            let state = Arc::clone(self);
            let account_id = account_id.to_string();
            let owner_flight = Arc::clone(&flight);
            tokio::spawn(async move {
                let refresh_started = std::time::Instant::now();
                let mut started_event = AuditEvent::new("oauth.refresh.started");
                started_event.provider_type = Some(provider_type.as_str().to_string());
                started_event.account_ref = Some(opaque_ref("account", &account_id));
                started_event.operation = Some(if force { "forced" } else { "scheduled" }.into());
                started_event.stage = Some("oauth_refresh".to_string());
                started_event.outcome = Some("started".to_string());
                state.emit_audit_event_best_effort(started_event);
                tracing::info!(
                    target: "cc_switch_server::request_audit",
                    event = "oauth.refresh.started",
                    provider_type = provider_type.as_str(),
                    account_ref = %opaque_ref("account", &account_id),
                    forced = force,
                    "OAuth refresh started"
                );
                let result =
                    match std::panic::AssertUnwindSafe(state.refresh_managed_account_owner(
                        provider_type,
                        &account_id,
                        expected_auth_identity_generation,
                        force,
                        refresh_generation,
                        access,
                    ))
                    .catch_unwind()
                    .await
                    {
                        Ok(result) => result,
                        Err(_) => {
                            state
                                .fail_closed_managed_account_refresh_panic(
                                    provider_type,
                                    &account_id,
                                    refresh_generation,
                                    refresh_started.elapsed(),
                                )
                                .await;
                            Err(ManagedAccountRefreshError::Refresh {
                                status_code: 500,
                                message: "managed account refresh owner panicked".to_string(),
                                retry_after_ms: None,
                            })
                        }
                    };
                record_managed_refresh_terminal_audit(
                    &state,
                    provider_type,
                    &account_id,
                    force,
                    refresh_started.elapsed(),
                    &result,
                );
                let _ = owner_flight.result.send(Some(result));
                state
                    .managed_account_refreshes
                    .complete(&key, &owner_flight);
            });
        }
        flight.wait().await
    }

    async fn fail_closed_managed_account_refresh_panic(
        self: &Arc<Self>,
        provider_type: ProviderType,
        account_id: &str,
        refresh_generation: (u64, u64),
        elapsed: Duration,
    ) {
        crate::metrics::record_oauth_refresh_attempt(
            provider_type.as_str(),
            "outcome_unknown",
            elapsed,
            true,
        );
        let account = self
            .find_account_for_provider(provider_type, account_id)
            .await
            .filter(|account| {
                (
                    account.auth_identity_generation,
                    account.token_refresh_generation,
                ) == refresh_generation
            });
        let Some(account) = account else {
            tracing::warn!(
                provider_type = %provider_type.as_str(),
                "managed OAuth refresh owner panicked after credentials changed; live credentials were preserved"
            );
            return;
        };
        let updated = match self
            .commit_native_refresh_failure(
                &account,
                "OAuth refresh owner panicked; refresh outcome is unknown".to_string(),
                crate::domain::accounts::oauth::OAuthErrorKind::Unknown,
                true,
            )
            .await
        {
            Ok(Some(updated)) if native_refresh_snapshot_matches(&updated, &account) => updated,
            Ok(_) => return,
            Err(error) => {
                tracing::error!(
                    account_id = %account.id,
                    provider_type = %account.provider_type.as_str(),
                    %error,
                    "could not isolate OAuth credentials after refresh owner panic"
                );
                return;
            }
        };
        if let Err(error) = self
            .refresh_account_runtime_metadata_if_changed(&account, &updated)
            .await
        {
            tracing::warn!(
                account_id = %account.id,
                provider_type = %account.provider_type.as_str(),
                %error,
                "refresh owner panic isolation Share metadata sync remains pending"
            );
        }
    }

    async fn refresh_managed_account_owner(
        self: &Arc<Self>,
        provider_type: ProviderType,
        account_id: &str,
        expected_auth_identity_generation: Option<u64>,
        force: bool,
        refresh_generation_before_lock: (u64, u64),
        access: ManagedAccountRefreshAccess,
    ) -> Result<(), ManagedAccountRefreshError> {
        let now = crate::infra::time::now_ms() as i64;
        let account = {
            let accounts = self.accounts.read().await;
            accounts
                .find_for_provider(provider_type, Some(account_id))
                .cloned()
        };
        let Some(account) = account else {
            return if expected_auth_identity_generation.is_some() {
                Err(ManagedAccountRefreshError::NotFound)
            } else {
                Ok(())
            };
        };
        ensure_account_identity_generation(
            &account,
            provider_type,
            expected_auth_identity_generation,
        )?;
        if (
            account.auth_identity_generation,
            account.token_refresh_generation,
        ) != refresh_generation_before_lock
        {
            return Ok(());
        }
        if !force && !account_needs_native_refresh(&account, now) {
            return Ok(());
        }

        let mut refresh_guard = self
            .account_refresh_locks
            .lock(account.provider_type, &account.id)
            .await;

        let _active_account_guard = if access == ManagedAccountRefreshAccess::ActiveAccount
            && provider_type == ProviderType::CodexOAuth
        {
            Some(self.codex_active_account_operations.read().await)
        } else {
            None
        };

        let account = {
            let accounts = self.accounts.read().await;
            ensure_managed_account_refresh_access(&accounts, provider_type, account_id, access)?;
            accounts
                .find_for_provider(provider_type, Some(account_id))
                .cloned()
        }
        .ok_or(ManagedAccountRefreshError::NotFound)?;
        ensure_account_identity_generation(
            &account,
            provider_type,
            expected_auth_identity_generation,
        )?;
        if let Some(failure) = refresh_guard.coalesced_native_failure_for(&account) {
            return Err(ManagedAccountRefreshError::Refresh {
                status_code: failure.status_code,
                message: failure.public_message.clone().unwrap_or_else(|| {
                    managed_account_refresh_public_message(failure.kind).to_string()
                }),
                retry_after_ms: failure.retry_after_ms,
            });
        }
        if (
            account.auth_identity_generation,
            account.token_refresh_generation,
        ) != refresh_generation_before_lock
        {
            return Ok(());
        }
        if !force && !account_needs_native_refresh(&account, now) {
            return Ok(());
        }
        if self.credential_persistence_degraded() {
            return Err(ManagedAccountRefreshError::CredentialPersistenceDegraded);
        }

        #[cfg(test)]
        if self
            .managed_account_refresh_panics
            .fetch_update(
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
                |remaining| remaining.checked_sub(1),
            )
            .is_ok()
        {
            panic!("injected managed account refresh owner panic");
        }

        let http_client = self.http_client().await;
        let interval_ms = self.oauth_quota_refresh_interval_ms().await;
        let refresh_started = std::time::Instant::now();
        let refresh_result = tokio::time::timeout(
            MANAGED_ACCOUNT_REFRESH_DEADLINE,
            self.execute_native_account_refresh_with_recovery(
                &http_client,
                &account,
                now,
                interval_ms,
                &mut refresh_guard,
            ),
        )
        .await
        .unwrap_or_else(|_| {
            let result = Err(AccountRefreshFailure::outcome_unknown(
                "OAuth refresh outcome is unknown after the 30 second owner deadline",
            ));
            record_refresh_flight_failure(&mut refresh_guard, &account, &result);
            result
        });
        let (refresh_outcome, outcome_unknown) = match &refresh_result {
            Ok(_) => ("receipt_validated", false),
            Err(error) if error.outcome_unknown => ("outcome_unknown", true),
            Err(error) if error.retryable => ("retryable_error", false),
            Err(error)
                if error.kind == crate::domain::accounts::oauth::OAuthErrorKind::InvalidGrant =>
            {
                ("invalid_grant", false)
            }
            Err(_) => ("terminal_error", false),
        };
        crate::metrics::record_oauth_refresh_attempt(
            provider_type.as_str(),
            refresh_outcome,
            refresh_started.elapsed(),
            outcome_unknown,
        );
        let update = match refresh_result {
            Ok(update) => update,
            Err(error) => {
                let diagnostic = redact_account_error_for_log(&account, &error.message);
                tracing::warn!(
                    account_id = %account.id,
                    provider_type = %account.provider_type.as_str(),
                    error_kind = ?error.kind,
                    error = %diagnostic,
                    "managed OAuth account refresh failed"
                );
                let updated = match self
                    .commit_native_refresh_failure(
                        &account,
                        error.message.clone(),
                        error.kind,
                        error.immediate_relogin,
                    )
                    .await
                {
                    Ok(updated) => updated,
                    Err(persist_error) => {
                        tracing::error!(
                            account_id = %account.id,
                            error = %persist_error,
                            "persisting managed OAuth refresh failure state failed"
                        );
                        None
                    }
                };
                if let Some(updated) = updated {
                    if let Err(sync_error) = self
                        .refresh_account_runtime_metadata_if_changed(&account, &updated)
                        .await
                    {
                        tracing::warn!(
                            account_id = %account.id,
                            error = %sync_error,
                            "managed account refresh failure Share descriptor sync remains pending"
                        );
                    }
                }
                return Err(ManagedAccountRefreshError::Refresh {
                    status_code: error.status_code,
                    message: managed_account_refresh_public_message(error.kind).to_string(),
                    retry_after_ms: error.retry_after_ms,
                });
            }
        };

        let updated = match self.commit_native_refresh_success(&account, update).await {
            Ok(updated) => updated,
            Err(error) => {
                if error.is_superseded() {
                    return Err(ManagedAccountRefreshError::Refresh {
                        status_code: 409,
                        message: "managed account credentials changed during OAuth refresh"
                            .to_string(),
                        retry_after_ms: None,
                    });
                }
                let persistence_degraded = error.is_persistence_degraded();
                let (status_code, public_message, retryable) = if persistence_degraded {
                    (
                        503,
                        "rotated credentials are live but durable persistence is degraded",
                        true,
                    )
                } else {
                    (500, "managed OAuth credential state commit failed", false)
                };
                let failure_account = if persistence_degraded {
                    self.find_account_by_id(&account.id)
                        .await
                        .unwrap_or_else(|| account.clone())
                } else {
                    account.clone()
                };
                refresh_guard.record_failure(AccountRefreshFlightFailure::for_account(
                    &failure_account,
                    AccountRefreshFlightStage::NativeRefresh,
                    AccountRefreshFlightFailureDetails {
                        status_code,
                        upstream_status: None,
                        message: error.to_string(),
                        public_message: Some(public_message.to_string()),
                        kind: crate::domain::accounts::oauth::OAuthErrorKind::Unknown,
                        retryable,
                        retry_after_ms: None,
                        immediate_relogin: false,
                    },
                ));
                if !persistence_degraded {
                    tracing::error!(
                        account_id = %account.id,
                        error = %error,
                        "managed OAuth credential state commit failed"
                    );
                    return Err(ManagedAccountRefreshError::Refresh {
                        status_code,
                        message: public_message.to_string(),
                        retry_after_ms: None,
                    });
                }
                let updated = self.find_account_by_id(&account.id).await;
                if let Some(updated) = updated.as_ref() {
                    if let Err(sync_error) = self
                        .refresh_account_runtime_metadata_if_changed(&account, updated)
                        .await
                    {
                        tracing::warn!(
                            account_id = %account.id,
                            error = %sync_error,
                            "degraded OAuth refresh Share descriptor sync remains pending"
                        );
                    }
                }
                tracing::error!(
                    account_id = %account.id,
                    error = %error,
                    "managed OAuth refresh entered credential persistence degraded mode"
                );
                return Err(ManagedAccountRefreshError::Refresh {
                    status_code,
                    message: public_message.to_string(),
                    retry_after_ms: None,
                });
            }
        };
        if let Err(error) = self
            .refresh_account_runtime_metadata_if_changed(&account, &updated)
            .await
        {
            tracing::warn!(
                account_id = %account.id,
                %error,
                "managed account refresh Share descriptor sync remains pending"
            );
        }
        Ok(())
    }

    pub async fn ensure_gemini_v1internal_project(
        self: &Arc<Self>,
        provider_type: ProviderType,
        account_id: &str,
    ) -> Result<(), ManagedAccountRefreshError> {
        self.ensure_gemini_v1internal_project_inner(provider_type, account_id, None)
            .await
    }

    pub async fn ensure_gemini_v1internal_project_for_generation(
        self: &Arc<Self>,
        provider_type: ProviderType,
        account_id: &str,
        expected_auth_identity_generation: u64,
    ) -> Result<(), ManagedAccountRefreshError> {
        self.ensure_gemini_v1internal_project_inner(
            provider_type,
            account_id,
            Some(expected_auth_identity_generation),
        )
        .await
    }

    async fn ensure_gemini_v1internal_project_inner(
        self: &Arc<Self>,
        provider_type: ProviderType,
        account_id: &str,
        expected_auth_identity_generation: Option<u64>,
    ) -> Result<(), ManagedAccountRefreshError> {
        if !matches!(
            provider_type,
            ProviderType::GeminiCli | ProviderType::AntigravityOAuth | ProviderType::AgyOAuth
        ) {
            return Ok(());
        }

        let initial = self
            .find_account_for_provider(provider_type, account_id)
            .await
            .ok_or(ManagedAccountRefreshError::NotFound)?;
        ensure_account_identity_generation(
            &initial,
            provider_type,
            expected_auth_identity_generation,
        )?;
        if gemini_v1internal_project_id(&initial).is_some() {
            return Ok(());
        }

        let mut project_guard = self
            .gemini_project_locks
            .lock(provider_type, account_id)
            .await;
        let mut refresh_guard = self
            .account_refresh_locks
            .lock(provider_type, account_id)
            .await;
        let mut account = self
            .find_account_for_provider(provider_type, account_id)
            .await
            .ok_or(ManagedAccountRefreshError::NotFound)?;
        ensure_account_identity_generation(
            &account,
            provider_type,
            expected_auth_identity_generation,
        )?;
        if gemini_v1internal_project_id(&account).is_some() {
            return Ok(());
        }
        if let Some(failure) = project_guard
            .coalesced_gemini_project_failure_for(&account)
            .or_else(|| refresh_guard.coalesced_native_failure_for(&account))
        {
            return Err(ManagedAccountRefreshError::Refresh {
                status_code: failure.status_code,
                message: failure
                    .public_message
                    .clone()
                    .unwrap_or_else(|| "Gemini Code Assist project discovery failed".to_string()),
                retry_after_ms: failure.retry_after_ms,
            });
        }
        if self.credential_persistence_degraded() {
            return Err(ManagedAccountRefreshError::CredentialPersistenceDegraded);
        }
        if account.needs_relogin {
            return Err(ManagedAccountRefreshError::Refresh {
                status_code: 401,
                message: "managed account must sign in again before project discovery".to_string(),
                retry_after_ms: None,
            });
        }

        let now = crate::infra::time::now_ms().min(i64::MAX as u128) as i64;
        if account.last_refresh_error.is_some() {
            if let Some(next_refresh_at) = account.quota_next_refresh_at {
                if next_refresh_at > now {
                    return Err(ManagedAccountRefreshError::Refresh {
                        status_code: 429,
                        message: "Gemini Code Assist project discovery is cooling down after a failed request"
                            .to_string(),
                        retry_after_ms: Some(next_refresh_at.saturating_sub(now)),
                    });
                }
            }
        }

        let http_client = self.http_client().await;
        let timeout_ms = self.oauth_quota_refresh_timeout_ms().await;
        let mut retried_after_unauthorized = false;
        loop {
            match load_gemini_v1internal_project(&http_client, &account, now, timeout_ms).await {
                Ok(update) => {
                    let updated = match self.commit_gemini_project_update(&account, update).await {
                        Ok(Ok(updated)) => updated,
                        Ok(Err(GeminiProjectCommitSkip::Stale(live)))
                            if expected_auth_identity_generation.is_none_or(|expected| {
                                live.auth_identity_generation == expected
                            }) && gemini_v1internal_project_id(&live).is_some() =>
                        {
                            return Ok(())
                        }
                        Ok(Err(GeminiProjectCommitSkip::Stale(_))) => {
                            return Err(ManagedAccountRefreshError::Refresh {
                                status_code: 409,
                                message: "managed account changed during project discovery"
                                    .to_string(),
                                retry_after_ms: None,
                            })
                        }
                        Ok(Err(GeminiProjectCommitSkip::NotFound)) => {
                            return Err(ManagedAccountRefreshError::NotFound)
                        }
                        Err(error) => {
                            let retry_after_ms = QUOTA_FAILURE_COOLDOWN_MS;
                            let public_message =
                                "Gemini Code Assist project metadata could not be persisted"
                                    .to_string();
                            tracing::error!(
                                account_id = %account.id,
                                provider_type = %account.provider_type.as_str(),
                                %error,
                                "persisting Gemini Code Assist project metadata failed"
                            );
                            project_guard.record_failure(AccountRefreshFlightFailure::for_account(
                                &account,
                                AccountRefreshFlightStage::GeminiProjectDiscovery,
                                AccountRefreshFlightFailureDetails {
                                    status_code: 500,
                                    upstream_status: None,
                                    message: error.to_string(),
                                    public_message: Some(public_message.clone()),
                                    kind: crate::domain::accounts::oauth::OAuthErrorKind::Unknown,
                                    retryable: true,
                                    retry_after_ms: Some(retry_after_ms),
                                    immediate_relogin: false,
                                },
                            ));
                            return Err(ManagedAccountRefreshError::Refresh {
                                status_code: 500,
                                message: public_message,
                                retry_after_ms: Some(retry_after_ms),
                            });
                        }
                    };
                    if gemini_v1internal_project_id(&updated).is_none() {
                        return Err(ManagedAccountRefreshError::Refresh {
                            status_code: 502,
                            message: "loadCodeAssist returned no usable projectId".to_string(),
                            retry_after_ms: None,
                        });
                    }
                    if let Err(error) = self
                        .refresh_account_subscription_metadata(
                            updated.provider_type,
                            Some(&updated.id),
                        )
                        .await
                    {
                        tracing::warn!(
                            account_id = %updated.id,
                            %error,
                            "Gemini project discovery Share metadata sync remains pending"
                        );
                    }
                    return Ok(());
                }
                Err(error)
                    if error.upstream_status == Some(401)
                        && !retried_after_unauthorized
                        && !account.needs_relogin
                        && account
                            .refresh_token
                            .as_deref()
                            .is_some_and(|token| !token.trim().is_empty()) =>
                {
                    retried_after_unauthorized = true;
                    let recovery_auth_identity_generation = account.auth_identity_generation;
                    refresh_guard.release();
                    let refresh_result = self
                        .refresh_managed_account_now_for_generation(
                            provider_type,
                            account_id,
                            recovery_auth_identity_generation,
                        )
                        .await;
                    if let Err(error) = refresh_result {
                        let failure_account = self
                            .find_account_for_provider(provider_type, account_id)
                            .await
                            .unwrap_or_else(|| account.clone());
                        project_guard.record_failure(AccountRefreshFlightFailure::for_account(
                            &failure_account,
                            AccountRefreshFlightStage::NativeRefresh,
                            managed_refresh_flight_failure_details(&error),
                        ));
                        return Err(error);
                    }
                    refresh_guard = self
                        .account_refresh_locks
                        .lock(provider_type, account_id)
                        .await;
                    account = self
                        .find_account_for_provider(provider_type, account_id)
                        .await
                        .ok_or(ManagedAccountRefreshError::NotFound)?;
                    ensure_account_identity_generation(
                        &account,
                        provider_type,
                        Some(recovery_auth_identity_generation),
                    )?;
                    if gemini_v1internal_project_id(&account).is_some() {
                        return Ok(());
                    }
                }
                Err(error) => {
                    let next_refresh_at = error
                        .next_refresh_at
                        .unwrap_or_else(|| now.saturating_add(QUOTA_FAILURE_COOLDOWN_MS));
                    let diagnostic = redact_account_error_for_log(&account, &error.message);
                    let mut update = error
                        .partial_update
                        .map(|update| *update)
                        .unwrap_or_default();
                    update.quota_next_refresh_at = Some(next_refresh_at);
                    update.last_refresh_error = Some(diagnostic.clone());
                    let commit = self.commit_gemini_project_update(&account, update).await;
                    if let Err(commit_error) = &commit {
                        tracing::error!(
                            account_id = %account.id,
                            provider_type = %account.provider_type.as_str(),
                            error = %commit_error,
                            "persisting Gemini project discovery failure cooldown failed"
                        );
                    }
                    let public_message = "Gemini Code Assist project discovery failed".to_string();
                    let retry_after_ms = Some(next_refresh_at.saturating_sub(now));
                    project_guard.record_failure(AccountRefreshFlightFailure::for_account(
                        &account,
                        AccountRefreshFlightStage::GeminiProjectDiscovery,
                        AccountRefreshFlightFailureDetails {
                            status_code: error.status_code,
                            upstream_status: error.upstream_status,
                            message: diagnostic,
                            public_message: Some(public_message.clone()),
                            kind: crate::domain::accounts::oauth::OAuthErrorKind::Unknown,
                            retryable: error.retryable,
                            retry_after_ms,
                            immediate_relogin: false,
                        },
                    ));
                    return Err(ManagedAccountRefreshError::Refresh {
                        status_code: error.status_code,
                        message: public_message,
                        retry_after_ms,
                    });
                }
            }
        }
    }

    async fn commit_gemini_project_update(
        self: &Arc<Self>,
        expected: &Account,
        update: AccountRefreshUpdate,
    ) -> anyhow::Result<Result<Account, GeminiProjectCommitSkip>> {
        #[cfg(test)]
        if self
            .gemini_project_commit_failures
            .fetch_update(
                std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
                |remaining| remaining.checked_sub(1),
            )
            .is_ok()
        {
            anyhow::bail!("injected Gemini project metadata persistence failure");
        }
        let expected = expected.clone();
        self.try_mutate_accounts_immediate(move |accounts| {
            let current = accounts
                .accounts
                .iter()
                .find(|account| {
                    account.id == expected.id && account.provider_type == expected.provider_type
                })
                .cloned()
                .ok_or(GeminiProjectCommitSkip::NotFound)?;
            if !native_refresh_snapshot_matches(&current, &expected)
                || current.profile != expected.profile
                || current.subscription_level != expected.subscription_level
            {
                return Err(GeminiProjectCommitSkip::Stale(Box::new(current)));
            }
            accounts
                .mark_refresh_success(&expected.id, update)
                .ok_or(GeminiProjectCommitSkip::NotFound)
        })
        .await
    }

    pub(crate) async fn commit_account_quota_refresh_update(
        self: &Arc<Self>,
        expected: &Account,
        update: AccountRefreshUpdate,
    ) -> anyhow::Result<Result<Account, AccountQuotaCommitSkip>> {
        let expected = expected.clone();
        self.try_mutate_accounts_immediate(move |accounts| {
            let current = accounts
                .accounts
                .iter()
                .find(|account| {
                    account.id == expected.id && account.provider_type == expected.provider_type
                })
                .cloned()
                .ok_or(AccountQuotaCommitSkip::NotFound)?;
            if !quota_refresh_snapshot_matches(&current, &expected) {
                return Err(AccountQuotaCommitSkip::Stale(Box::new(current)));
            }
            accounts
                .mark_refresh_success(&expected.id, update)
                .ok_or(AccountQuotaCommitSkip::NotFound)
        })
        .await
    }

    pub fn schedule_gemini_v1internal_project_enrichment(
        self: &Arc<Self>,
        provider_type: ProviderType,
        account_id: &str,
    ) {
        if !matches!(
            provider_type,
            ProviderType::GeminiCli | ProviderType::AntigravityOAuth | ProviderType::AgyOAuth
        ) {
            return;
        }
        let state = Arc::clone(self);
        let account_id = account_id.to_string();
        tokio::spawn(async move {
            #[cfg(test)]
            {
                let explicitly_mocked = state
                    .find_account_for_provider(provider_type, &account_id)
                    .await
                    .and_then(|account| account.raw)
                    .and_then(|raw| raw.get("testGeminiCodeAssistBaseUrl").cloned())
                    .and_then(|value| value.as_str().map(str::to_string))
                    .is_some();
                if !explicitly_mocked {
                    return;
                }
            }
            if state
                .refresh_managed_account_if_needed(provider_type, &account_id)
                .await
                .is_err()
            {
                return;
            }
            if state
                .ensure_gemini_v1internal_project(provider_type, &account_id)
                .await
                .is_err()
            {
                tracing::debug!(
                    account_id,
                    provider_type = %provider_type.as_str(),
                    "best-effort Gemini project enrichment remains pending"
                );
            }
        });
    }

