    #[tokio::test]
    async fn grok_capability_observation_throttles_identical_state_but_commits_transitions() {
        let state = test_state();
        let account = state
            .mutate_accounts_immediate(|accounts| {
                accounts.upsert(refresh_test_account_input(
                    "grok-capability-state-transition",
                    ProviderType::GrokOAuth,
                    Some("owner@example.com"),
                    "access",
                    "refresh",
                    i64::MAX,
                ))
            })
            .await
            .unwrap();
        let capability = crate::domain::accounts::store::GrokAccountCapability::VideoGeneration;
        let unsupported =
            crate::domain::accounts::capability_evidence::AccountCapabilityObservationState::Unsupported;

        assert!(state
            .record_grok_capability_observation_if_current(
                &account.id,
                capability,
                CurrentAccountCapabilityObservation {
                    provider_type: account.provider_type,
                    auth_identity_generation: account.auth_identity_generation,
                    state: unsupported,
                    source: "media_response",
                    reason: Some("endpoint_not_supported"),
                    expires_at_ms: None,
                },
            )
            .await
            .unwrap());
        assert!(!state
            .record_grok_capability_observation_if_current(
                &account.id,
                capability,
                CurrentAccountCapabilityObservation {
                    provider_type: account.provider_type,
                    auth_identity_generation: account.auth_identity_generation,
                    state: unsupported,
                    source: "media_response",
                    reason: Some("endpoint_not_supported"),
                    expires_at_ms: None,
                },
            )
            .await
            .unwrap());
        assert!(state
            .record_grok_capability_evidence_if_current(
                &account.id,
                account.provider_type,
                account.auth_identity_generation,
                capability,
                "upstream_success",
            )
            .await
            .unwrap());

        let current = state.find_account_by_id(&account.id).await.unwrap();
        let observation = current
            .capability_observations
            .get("grok_code_plan:video_generation")
            .unwrap();
        assert_eq!(
            observation.state,
            crate::domain::accounts::capability_evidence::AccountCapabilityObservationState::Supported
        );
        assert_eq!(observation.source, "upstream_success");
        assert!(observation.reason.is_none());
    }

    #[tokio::test]
    async fn stale_refresh_success_and_failure_cannot_overwrite_reauthorization() {
        let state = test_state();
        let stale = state
            .mutate_accounts_immediate(|accounts| {
                accounts.upsert(refresh_test_account_input(
                    "grok-refresh-cas",
                    ProviderType::GrokOAuth,
                    Some("old@example.com"),
                    "old-access",
                    "old-refresh",
                    1,
                ))
            })
            .await
            .unwrap();
        let reauthorized = state
            .mutate_accounts_immediate(|accounts| {
                accounts.upsert(refresh_test_account_input(
                    "grok-refresh-cas",
                    ProviderType::GrokOAuth,
                    Some("new@example.com"),
                    "reauthorized-access",
                    "reauthorized-refresh",
                    i64::MAX,
                ))
            })
            .await
            .unwrap();
        assert!(reauthorized.auth_identity_generation > stale.auth_identity_generation);
        assert!(reauthorized.token_refresh_generation > stale.token_refresh_generation);

        let after_success = match state
            .commit_native_refresh_success(
                &stale,
                AccountRefreshUpdate {
                    access_token: Some("stale-refresh-access".to_string()),
                    refresh_token: Some("stale-refresh-token".to_string()),
                    ..Default::default()
                },
            )
            .await
        {
            Err(NativeRefreshCommitError::Superseded(live)) => *live,
            other => panic!("expected superseded refresh commit, got {other:?}"),
        };
        assert_eq!(
            after_success.access_token.as_deref(),
            Some("reauthorized-access")
        );

        let after_failure = state
            .commit_native_refresh_failure(
                &stale,
                "invalid_grant".to_string(),
                crate::domain::accounts::oauth::OAuthErrorKind::InvalidGrant,
                false,
            )
            .await
            .unwrap()
            .unwrap();
        assert!(!after_failure.needs_relogin);
        assert!(after_failure.last_refresh_error.is_none());

        let persisted = AccountStore::load_or_default(&state.config_dir).unwrap();
        let persisted = persisted
            .find_for_provider(ProviderType::GrokOAuth, Some("grok-refresh-cas"))
            .unwrap();
        assert_eq!(
            persisted.refresh_token.as_deref(),
            Some("reauthorized-refresh")
        );
    }

    #[test]
    fn stale_persistence_success_cannot_clear_a_newer_failure_generation() {
        let state = test_state();
        state.mark_credential_persistence_degraded();
        let stale_generation = state
            .credential_persistence_state
            .load(std::sync::atomic::Ordering::Acquire);
        state.mark_credential_persistence_degraded();

        assert!(!state.clear_credential_persistence_degraded_if_unchanged(stale_generation));
        assert!(state.credential_persistence_degraded());

        let current_generation = state
            .credential_persistence_state
            .load(std::sync::atomic::Ordering::Acquire);
        assert!(state.clear_credential_persistence_degraded_if_unchanged(current_generation));
        assert!(!state.credential_persistence_degraded());
    }

    #[tokio::test]
    async fn persistence_coordinators_prevent_delayed_snapshots_from_winning() {
        fn usage_log(request_id: &str) -> UsageLog {
            let mut log = UsageLog::new(
                AppKind::Codex,
                "persistence-provider".to_string(),
                "Persistence Provider".to_string(),
                ProviderType::Codex,
                200,
                1,
                UsageModelMetadata::default(),
                TokenUsage::default(),
            );
            log.request_id = request_id.to_string();
            log
        }

        let state = test_state();
        let config_dir = state.config_dir.clone();

        state.config_persistence.delay_next_persist(100);
        let delay_started = state.config_persistence.persist_delay_started.notified();
        let older_state = state.clone();
        let older = tokio::spawn(async move {
            older_state
                .mutate_config_immediate(|config| {
                    config.router.last_register_error = Some("older-config".to_string());
                    Ok(())
                })
                .await
                .unwrap();
        });
        tokio::time::timeout(Duration::from_secs(2), delay_started)
            .await
            .unwrap();
        let newer_state = state.clone();
        let newer = tokio::spawn(async move {
            newer_state
                .mutate_config_immediate(|config| {
                    config.router.last_register_error = Some("newer-config".to_string());
                    Ok(())
                })
                .await
                .unwrap();
        });
        older.await.unwrap();
        newer.await.unwrap();
        assert_eq!(
            ServerConfig::load_or_default(&config_dir)
                .unwrap()
                .router
                .last_register_error
                .as_deref(),
            Some("newer-config")
        );

        state.accounts_persistence.delay_next_persist(100);
        let delay_started = state.accounts_persistence.persist_delay_started.notified();
        let older_state = state.clone();
        let older = tokio::spawn(async move {
            older_state
                .mutate_accounts_immediate(|accounts| {
                    accounts.upsert(refresh_test_account_input(
                        "persistence-account",
                        ProviderType::GrokOAuth,
                        Some("older@example.com"),
                        "older-access",
                        "older-refresh",
                        i64::MAX,
                    ));
                })
                .await
                .unwrap();
        });
        tokio::time::timeout(Duration::from_secs(2), delay_started)
            .await
            .unwrap();
        let newer_state = state.clone();
        let newer = tokio::spawn(async move {
            newer_state
                .mutate_accounts_immediate(|accounts| {
                    accounts.upsert(refresh_test_account_input(
                        "persistence-account",
                        ProviderType::GrokOAuth,
                        Some("newer@example.com"),
                        "newer-access",
                        "newer-refresh",
                        i64::MAX,
                    ));
                })
                .await
                .unwrap();
        });
        older.await.unwrap();
        newer.await.unwrap();
        assert_eq!(
            AccountStore::load_or_default(&config_dir)
                .unwrap()
                .find_for_provider(ProviderType::GrokOAuth, Some("persistence-account"))
                .unwrap()
                .email
                .as_deref(),
            Some("newer@example.com")
        );

        state.usage_persistence.delay_next_persist(100);
        let delay_started = state.usage_persistence.persist_delay_started.notified();
        let older_state = state.clone();
        let older = tokio::spawn(async move {
            older_state
                .push_usage_log(usage_log("older-usage"))
                .await
                .unwrap();
        });
        tokio::time::timeout(Duration::from_secs(2), delay_started)
            .await
            .unwrap();
        let newer_state = state.clone();
        let newer = tokio::spawn(async move {
            newer_state
                .push_usage_log(usage_log("newer-usage"))
                .await
                .unwrap();
        });
        older.await.unwrap();
        newer.await.unwrap();
        assert_eq!(
            UsageStore::load_or_default(&config_dir)
                .unwrap()
                .logs
                .iter()
                .map(|log| log.request_id.as_str())
                .collect::<Vec<_>>(),
            vec!["older-usage", "newer-usage"]
        );

        state.shares_persistence.delay_next_persist(100);
        let delay_started = state.shares_persistence.persist_delay_started.notified();
        let older_state = state.clone();
        let older = tokio::spawn(async move {
            let mut input = router_sync_share_input("persistence-share", "persistence-provider");
            input.display_name = Some("Older Share".to_string());
            older_state
                .mutate_shares_immediate(|shares| shares.upsert(input))
                .await
                .unwrap()
                .unwrap();
        });
        tokio::time::timeout(Duration::from_secs(2), delay_started)
            .await
            .unwrap();
        let newer_state = state.clone();
        let newer = tokio::spawn(async move {
            let mut input = router_sync_share_input("persistence-share", "persistence-provider");
            input.display_name = Some("Newer Share".to_string());
            newer_state
                .mutate_shares_immediate(|shares| shares.upsert(input))
                .await
                .unwrap()
                .unwrap();
        });
        older.await.unwrap();
        newer.await.unwrap();
        assert_eq!(
            ShareStore::load_or_default(&config_dir)
                .unwrap()
                .get("persistence-share")
                .unwrap()
                .display_name
                .as_deref(),
            Some("Newer Share")
        );

        state.ui_settings_persistence.delay_next_persist(100);
        let delay_started = state
            .ui_settings_persistence
            .persist_delay_started
            .notified();
        let older_state = state.clone();
        let older = tokio::spawn(async move {
            older_state
                .mutate_ui_settings_immediate(|settings| {
                    settings.apply_patch(json!({"persistenceProbe": "older-ui"}));
                })
                .await
                .unwrap();
        });
        tokio::time::timeout(Duration::from_secs(2), delay_started)
            .await
            .unwrap();
        let newer_state = state.clone();
        let newer = tokio::spawn(async move {
            newer_state
                .mutate_ui_settings_immediate(|settings| {
                    settings.apply_patch(json!({"persistenceProbe": "newer-ui"}));
                })
                .await
                .unwrap();
        });
        older.await.unwrap();
        newer.await.unwrap();
        assert_eq!(
            UiSettingsStore::load_or_default(&config_dir).unwrap().value["persistenceProbe"],
            json!("newer-ui")
        );

        drop(state);
        fs::remove_dir_all(config_dir).unwrap();
    }

    #[test]
    fn restore_tunnel_logic_skips_manually_stopped_client() {
        let mut config = ServerConfig::empty();
        assert!(!should_restore_client_tunnel(&config, None));

        config.auth.password_hash = Some("configured".to_string());
        config.owner.email = Some("owner@example.com".to_string());
        config.router.url = Some("https://router.example.com".to_string());
        config.client.tunnel_subdomain = Some("restore-client".to_string());
        config.client.tunnel_status = Some("claim_failed".to_string());
        assert!(should_restore_client_tunnel(&config, None));

        config.client.tunnel_status = Some("claim_pending".to_string());
        assert!(should_restore_client_tunnel(&config, None));
        assert!(should_restore_client_tunnel(
            &config,
            Some(&TunnelRuntimeStatus {
                status: "connected".to_string(),
                ..TunnelRuntimeStatus::default()
            })
        ));
        assert!(!should_restore_client_tunnel(
            &config,
            Some(&TunnelRuntimeStatus {
                status: "stopped".to_string(),
                ..TunnelRuntimeStatus::default()
            })
        ));
    }

    #[test]
    fn share_in_flight_tracker_enforces_limit_until_guard_drops() {
        let tracker = Arc::new(ShareInFlightTracker::default());
        let first = tracker.try_acquire("share-1", Some(1));

        assert!(first.is_some());
        assert!(tracker.has_in_flight("share-1"));
        assert!(!tracker.has_in_flight("share-2"));
        assert!(tracker.try_acquire("share-1", Some(1)).is_none());
        assert!(tracker.try_acquire("share-2", Some(1)).is_some());

        drop(first);
        assert!(!tracker.has_in_flight("share-1"));
        assert!(tracker.try_acquire("share-1", Some(1)).is_some());
    }

    #[tokio::test]
    async fn share_delete_is_blocked_until_in_flight_accounting_finishes() {
        let state = test_state();
        let share = state
            .mutate_shares_immediate(|store| {
                store.upsert(router_sync_share_input(
                    "inflightdelete",
                    "provider-before-delete",
                ))
            })
            .await
            .unwrap()
            .unwrap();
        let (_invocation, guard) = state
            .validate_and_acquire_share_invocation(
                &share.id,
                AppKind::Codex,
                Some("owner@example.com"),
                crate::infra::time::now_ms() as i64,
            )
            .await
            .unwrap();

        assert_eq!(
            state
                .delete_share_immediate_at_revision(&share.id, share.config_revision)
                .await
                .unwrap(),
            Err(ConditionalShareDeleteError::InFlight)
        );
        assert_eq!(
            state.delete_share_immediate(&share.id).await.unwrap(),
            Err(ShareDeleteError::InFlight)
        );

        state
            .record_share_invocation_result(&share.id, None, 37, 1)
            .await;
        let accounted = state.shares.read().await.get(&share.id).cloned().unwrap();
        assert_eq!(accounted.requests_count, 1);
        assert_eq!(accounted.tokens_used, 37);
        drop(guard);
        let deleted = state
            .delete_share_immediate(&share.id)
            .await
            .unwrap()
            .unwrap();
        assert!(deleted.is_some());

        let recreated = state
            .mutate_shares_immediate(|store| {
                store.upsert(router_sync_share_input(
                    "inflightdelete",
                    "provider-after-delete",
                ))
            })
            .await
            .unwrap()
            .unwrap();
        assert_eq!(recreated.requests_count, 0);
        assert_eq!(recreated.tokens_used, 0);
    }

    #[test]
    fn share_in_flight_tracker_intersects_share_and_user_limits() {
        let tracker = Arc::new(ShareInFlightTracker::default());
        let alice = tracker
            .try_acquire_for_user("share-1", Some(2), Some("Alice@Example.com"), Some(1))
            .expect("alice should acquire her first slot");
        assert!(matches!(
            tracker.try_acquire_for_user("share-1", Some(2), Some("alice@example.com"), Some(1)),
            Err(ShareInFlightAcquireError::UserLimit {
                current: 1,
                limit: 1
            })
        ));

        let bob = tracker
            .try_acquire_for_user("share-1", Some(2), Some("bob@example.com"), Some(2))
            .expect("bob should use the remaining total slot");
        assert!(matches!(
            tracker.try_acquire_for_user("share-1", Some(2), Some("charlie@example.com"), Some(2)),
            Err(ShareInFlightAcquireError::ShareLimit {
                current: 2,
                limit: 2
            })
        ));

        drop(alice);
        assert!(tracker
            .try_acquire_for_user("share-1", Some(2), Some("charlie@example.com"), Some(1))
            .is_ok());
        drop(bob);
    }

    #[tokio::test]
    async fn share_user_parallel_limit_is_shared_across_api_surfaces() {
        let state = test_state();
        let mut input = router_sync_share_input("crosssurface", "codex-provider");
        input.bindings = vec![
            ShareBinding {
                app: AppKind::Claude,
                provider_id: "claude-provider".to_string(),
                provider_type: ProviderType::Claude,
            },
            ShareBinding {
                app: AppKind::Codex,
                provider_id: "codex-provider".to_string(),
                provider_type: ProviderType::Codex,
            },
        ];
        let share = state
            .mutate_shares_immediate(|store| store.upsert(input))
            .await
            .unwrap()
            .unwrap();
        state
            .mutate_shares_immediate(|store| {
                store
                    .shares
                    .iter_mut()
                    .find(|candidate| candidate.id == share.id)
                    .unwrap()
                    .user_grants
                    .get_mut("owner@example.com")
                    .unwrap()
                    .policy
                    .parallel_limit = Some(1);
            })
            .await
            .unwrap();

        let (_claude, guard) = state
            .validate_and_acquire_share_invocation(
                &share.id,
                AppKind::Claude,
                Some("owner@example.com"),
                crate::infra::time::now_ms() as i64,
            )
            .await
            .expect("Claude should acquire the user's shared slot");
        let rejection = state
            .validate_and_acquire_share_invocation(
                &share.id,
                AppKind::Codex,
                Some("owner@example.com"),
                crate::infra::time::now_ms() as i64,
            )
            .await
            .expect_err("Codex must share the same user slot");

        assert_eq!(rejection.reason, ShareRejectReason::UserParallelLimit);
        assert_eq!(
            rejection.concurrency,
            Some(ShareConcurrencyLimit {
                current: 1,
                limit: 1,
            })
        );

        drop(guard);
        assert!(state
            .validate_and_acquire_share_invocation(
                &share.id,
                AppKind::Codex,
                Some("owner@example.com"),
                crate::infra::time::now_ms() as i64,
            )
            .await
            .is_ok());
    }

    #[test]
    fn account_in_flight_tracker_enforces_limit_and_snapshots_load() {
        let tracker = Arc::new(AccountInFlightTracker::default());
        let guard = tracker
            .try_acquire(ProviderType::ClaudeOAuth, "acct-1", 1)
            .expect("first request should acquire account capacity");
        let other_account_guard = tracker
            .try_acquire(ProviderType::ClaudeOAuth, "acct-2", 1)
            .expect("a different account keeps an independent capacity limit");

        assert_eq!(
            tracker
                .snapshot()
                .current(ProviderType::ClaudeOAuth, "acct-1"),
            1
        );
        assert_eq!(
            tracker
                .counts
                .lock()
                .unwrap()
                .by_provider_type
                .get(ProviderType::ClaudeOAuth.as_str()),
            Some(&2)
        );
        assert!(matches!(
            tracker.try_acquire(ProviderType::ClaudeOAuth, "acct-1", 1),
            Err(AccountInFlightAcquireError {
                current: 1,
                limit: 1,
            })
        ));

        drop(guard);
        assert_eq!(
            tracker
                .counts
                .lock()
                .unwrap()
                .by_provider_type
                .get(ProviderType::ClaudeOAuth.as_str()),
            Some(&1)
        );
        drop(other_account_guard);
        assert!(!tracker
            .counts
            .lock()
            .unwrap()
            .by_provider_type
            .contains_key(ProviderType::ClaudeOAuth.as_str()));
        assert_eq!(
            tracker
                .snapshot()
                .current(ProviderType::ClaudeOAuth, "acct-1"),
            0
        );
        assert!(tracker
            .try_acquire(ProviderType::ClaudeOAuth, "acct-1", 1)
            .is_ok());
    }

    #[test]
    fn device_flow_principal_store_enforces_owner_and_expiry() {
        let mut store = DeviceFlowPrincipalStore::default();
        store.insert(
            ProviderType::CodexOAuth,
            "device-1".to_string(),
            "alice:admin".to_string(),
            2_000,
            1_000,
        );

        assert!(store.is_owned_by(ProviderType::CodexOAuth, "device-1", "alice:admin", 1_500));
        assert!(!store.is_owned_by(ProviderType::CodexOAuth, "device-1", "bob:admin", 1_500));
        assert!(!store.remove_for_principal(
            ProviderType::CodexOAuth,
            "device-1",
            "bob:admin",
            1_500
        ));
        assert!(store.remove_for_principal(
            ProviderType::CodexOAuth,
            "device-1",
            "alice:admin",
            1_500
        ));

        store.insert(
            ProviderType::GrokOAuth,
            "device-2".to_string(),
            "alice:admin".to_string(),
            2_000,
            1_000,
        );
        assert!(!store.is_owned_by(ProviderType::GrokOAuth, "device-2", "alice:admin", 2_000));

        for (provider_type, device_code, principal_id) in [
            (ProviderType::GitHubCopilot, "device-3", "alice:admin"),
            (ProviderType::GitHubCopilot, "device-4", "alice:admin"),
            (ProviderType::GitHubCopilot, "device-5", "bob:admin"),
            (ProviderType::KiroOAuth, "device-6", "alice:admin"),
        ] {
            store.insert(
                provider_type,
                device_code.to_string(),
                principal_id.to_string(),
                4_000,
                2_000,
            );
        }
        let removed =
            store.remove_all_for_principal(ProviderType::GitHubCopilot, "alice:admin", 3_000);
        assert_eq!(
            removed,
            vec!["device-3".to_string(), "device-4".to_string()]
        );
        assert!(store.is_owned_by(ProviderType::GitHubCopilot, "device-5", "bob:admin", 3_000));
        assert!(store.is_owned_by(ProviderType::KiroOAuth, "device-6", "alice:admin", 3_000));
    }

    #[test]
    fn control_nonce_cache_rejects_replay_within_window() {
        let cache = ControlNonceCache::default();

        assert!(cache.register("inst-1", "nonce-1", 10_000, 300_000));
        assert!(!cache.register("inst-1", "nonce-1", 11_000, 300_000));
        assert!(cache.register("inst-2", "nonce-1", 11_000, 300_000));
        assert!(cache.register("inst-1", "nonce-1", 400_001, 300_000));
    }

